// GENERATED by scripts/i18n/buildDescriptions.ts from scripts/i18n/desc/*.json — edit those, not this file.
// English description (whitespace-normalized) -> [Japanese, Traditional Chinese, Simplified Chinese].
export const DESCRIPTIONS: Record<string, [string, string, string]> = {
  "A compact reactor: a great deal of power.": ["小型の炉。大量の電力。", "小型反應爐：大量電力。", "小型反应堆：大量电力。"],
  "A dense urban core of roads, transit and commerce. Automobiles and power keep a city moving and trading — it runs on the cars its people drive.": ["道路、交通、商業が密集する都心。自動車と電力が都市の移動と交易を保つ。住民の乗る車で動く。", "道路、交通與商業密集的都市核心。汽車與電力讓城市持續運轉與交易——靠市民所開的車子運行。", "道路、交通与商业密集的都市核心。汽车与电力让城市持续运转与交易——靠市民所开的车子运行。"],
  "A faster warp field: every warp ship of the nation upgrades at once, no refit. Consumes exotic matter.": ["より速い歪曲場。国のすべての歪曲艦が改装なしで一斉に向上する。異種物質を消費する。", "更快的曲速場：國家所有曲速艦同時升級，無需改裝。消耗奇異物質。", "更快的曲速场：国家所有曲速舰同时升级，无需改装。消耗奇异物质。"],
  "A field that soaks up siege damage: more hit points and armour.": ["包囲の損害を吸収する力場。耐久と装甲が増える。", "吸收圍攻傷害的力場：更多生命值與裝甲。", "吸收围攻伤害的力场：更多生命值与装甲。"],
  "A finite natural reserve of hyperium or exotic matter on a planet, revealed by survey. A nation that owns the body and has the matching Extraction tech draws it a month at a time until it runs dry.": ["惑星にある超空間鉱か異種物質の有限な天然埋蔵量。調査で判明する。天体を所有し対応する採掘技術を持つ国が、枯渇するまで毎月採る。", "行星上有限的超空間礦或奇異物質天然儲量，經勘測後揭露。擁有該天體並具備相應開採科技的國家，每月開採直到枯竭。", "行星上有限的超空间矿或奇异物质天然储量，经勘测后揭露。拥有该天体并具备相应开采科技的国家，每月开采直到枯竭。"],
  "A fleet of ocean-going boats works the coast and the open sea, landing fish at the wharves. The boats are consumed as they wear out and are replaced — a world with sea turns ships into food.": ["外航漁船の船団が沿岸と外洋で漁をし、魚を岸壁に揚げる。船は老朽化すれば消費され置き換えられる。海のある世界は船を食料に変える。", "遠洋漁船隊在沿岸與公海作業，將漁獲卸於碼頭。船隻耗損後會被消耗並替換——有海的世界把船變成糧食。", "远洋渔船队在沿岸与公海作业，将渔获卸于码头。船只耗损后会被消耗并替换——有海的世界把船变成粮食。"],
  "A full colony: all its land, and it can raise armies. Every world a nation starts with is one.": ["完全な植民地。すべての土地を持ち、軍を編成できる。国が最初に持つ世界はすべてこれ。", "完整殖民地：擁有全部土地，可組建軍隊。國家初始擁有的世界皆屬此類。", "完整殖民地：拥有全部土地，可组建军队。国家初始拥有的世界皆属此类。"],
  "A ground anchor and climber station for a tether to orbit — fuel-free lift when paired with an orbital tether above.": ["軌道への索の地上基部と昇降機駅。上空の軌道索と組めば燃料なしの揚力。", "通往軌道之纜繩的地面錨座與爬升站——與上空軌道纜繩配對時可無燃料升空。", "通往轨道之缆绳的地面锚座与爬升站——与上空轨道缆绳配对时可无燃料升空。"],
  "A hull-spanning smart grid, the practical ceiling of what a single reactor core can feed — even so, the biggest weapons in service still don't come cheap.": ["船体全体に張り巡らせた賢い電力網。単一の炉心が賄える実用上の上限だが、それでも最大の兵器は依然として安くない。", "遍布艦體的智慧電網，是單一反應爐核心所能供應的實際上限——即便如此，最強的現役武器依然代價不菲。", "遍布舰体的智能电网，是单一反应堆核心所能供应的实际上限——即便如此，最强的现役武器依然代价不菲。"],
  "A hyperium-synthesis site: where Hyperium Synthesis turns exotic matter into hyperium, in orbit.": ["超空間鉱合成施設。超空間鉱合成が軌道上で異種物質を超空間鉱に変える場所。", "超空間礦合成站：超空間礦合成在軌道上將奇異物質轉化為超空間礦之處。", "超空间矿合成站：超空间矿合成在轨道上将奇异物质转化为超空间矿之处。"],
  "A merchant-marine berth: adds to the nation’s interstellar freight capacity.": ["商船隊の停泊所。国の恒星間貨物容量を増やす。", "商船隊泊位：增加國家的星際貨運量。", "商船队泊位：增加国家的星际货运量。"],
  "A merchant-marine berth: maximises INTERSTELLAR freight (trade between stars) at the cost of raw lift.": ["商船隊の停泊所。単純な揚力を犠牲に、恒星間貨物(星々の間の交易)を最大化する。", "商船隊泊位：以原始升力為代價，將星際貨運（恆星間貿易）最大化。", "商船队泊位：以原始升力为代价，将星际货运（恒星间贸易）最大化。"],
  "A microgravity laboratory: research points each month (Simple mode).": ["微小重力研究所。毎月研究点を生む(簡易モード)。", "微重力實驗室：每月產生研究點數（簡易模式）。", "微重力实验室：每月产生研究点数（简易模式）。"],
  "A nation's money. Each nation has its own, and its value against other currencies floats.": ["国のお金。各国が独自に持ち、他通貨に対する価値は変動する。", "一個國家的貨幣。各國各有其貨幣，對其他貨幣的價值浮動。", "一个国家的货币。各国各有其货币，对其他货币的价值浮动。"],
  "A navigator that plots every hyperspace jump itself, without a crew to get it wrong. Hyperspace Scouts can be refitted into Turing Scouts: jumps that never fail and a drive that recycles in a week.": ["乗員の失敗なしに、すべての超空間跳躍を自ら計算する航法装置。超空間偵察艇をチューリング偵察艇へ改装でき、跳躍は決して失敗せず、機関は一週間で再充填される。", "自行規劃每次超空間躍遷、不需船員也不會出錯的導航器。超空間偵察艇可改裝為圖靈偵察艇：躍遷永不失敗，引擎一週即可再次使用。", "自行规划每次超空间跃迁、不需船员也不会出错的导航器。超空间侦察艇可改装为图灵侦察艇：跃迁永不失败，引擎一周即可再次使用。"],
  "A new colony: little land to build on and no armies of its own. It becomes a planetary colony after 90 days with a patrol ship holding its orbit, no hostile warship there and no enemy on the ground.": ["新しい植民地。建てる土地はわずかで、自前の軍もない。巡回艦が軌道を保持し、敵艦も地上の敵もいない状態で90日たつと惑星植民地になる。", "新殖民地：可建造的土地很少，也沒有自己的軍隊。在巡邏艦守住軌道、無敵方戰艦且地面無敵人的情況下經過90天，即成為行星殖民地。", "新殖民地：可建造的土地很少，也没有自己的军队。在巡逻舰守住轨道、无敌方战舰且地面无敌人的情况下经过90天，即成为行星殖民地。"],
  "A promise to hold the currency at a fixed rate, defended by spending FX reserves. If the reserves run out, the peg breaks.": ["外貨準備を使って守る、通貨を固定相場に保つ約束。準備が尽きれば固定は崩れる。", "承諾以固定匯率維持貨幣，並動用外匯存底捍衛。存底耗盡，釘住即告破裂。", "承诺以固定汇率维持货币，并动用外汇储备捍卫。储备耗尽，钉住即告破裂。"],
  "A quick list of your battles, fleets, armies and colonies — click one to jump to it.": ["戦闘、艦隊、陸軍、植民地の早見表。クリックでそこへ飛ぶ。", "你的戰鬥、艦隊、陸軍與殖民地快速列表——點擊即可前往。", "你的战斗、舰队、陆军与殖民地快速列表——点击即可前往。"],
  "A rare form of matter with a higher mass-energy conversion rate than normal matter — fuels warp drives and their onboard systems.": ["通常物質より高い質量エネルギー変換率を持つ希少な物質。歪曲航法とその搭載系統の燃料。", "一種質能轉換率高於普通物質的稀有物質——曲速引擎及其艦載系統的燃料。", "一种质能转换率高于普通物质的稀有物质——曲速引擎及其舰载系统的燃料。"],
  "A reflective hull finish that scatters a portion of incoming laser fire — a direct, narrow counter to Directed Energy Weapons, and useful cover against passive optical detection besides.": ["入射するレーザーの一部を散乱させる反射性の船体塗装。指向性エネルギー兵器への直接的で限定的な対抗策であり、受動光学探知からの隠れ蓑にもなる。", "能散射部分來襲雷射的反射性艦體塗層——對定向能武器直接而有限的反制，也有助於躲避被動光學偵測。", "能散射部分来袭激光的反射性舰体涂层——对定向能武器直接而有限的反制，也有助于躲避被动光学侦测。"],
  "A savings buffer kept aside in good times, to draw on in a crisis or to pay off debt.": ["好況時に蓄え、危機に取り崩すか債務返済に使う貯蓄の緩衝材。", "景氣好時存下的儲蓄緩衝，危機時動用或用於償債。", "景气好时存下的储蓄缓冲，危机时动用或用于偿债。"],
  "A second independent power bus and load-balancing grid — lets a hull run meaningfully more equipment at once without browning out.": ["独立した第二の電力母線と負荷分散網。電圧低下なしに、船体がより多くの装備を同時に動かせる。", "第二條獨立電力匯流排與負載平衡電網——讓艦體能同時運轉更多裝備而不致電壓不足。", "第二条独立电力汇流排与负载平衡电网——让舰体能同时运转更多装备而不致电压不足。"],
  "A single drive module carrying both a hyperdrive and a warp drive: a hull that warps while it can and jumps when it must.": ["超空間航法と歪曲航法を併せ持つ単一の推進区画。歪曲できるうちは歪曲し、必要なら跳躍する船体。", "同時搭載超空間引擎與曲速引擎的單一推進模組：能曲速時曲速，必要時躍遷的艦體。", "同时搭载超空间引擎与曲速引擎的单一推进模组：能曲速时曲速，必要时跃迁的舰体。"],
  "A specialist hospital delivering far more healthcare from chemicals and power.": ["化学品と電力で、はるかに多くの医療を提供する専門病院。", "以化學品與電力提供遠更多醫療服務的專科醫院。", "以化学品与电力提供远更多医疗服务的专科医院。"],
  "A strongpoint: its holder’s units nearby fight 60% harder, and an invader must hold it to take the world.": ["拠点。保持者の近くの部隊は60%強く戦い、侵略者は世界を取るためにこれを握らねばならない。", "據點：持有者附近的部隊戰力提升60%，入侵者必須佔領它才能奪取該世界。", "据点：持有者附近的部队战力提升60%，入侵者必须占领它才能夺取该世界。"],
  "A tether from the ground to orbit — the space elevator. Fuel-free surface↔orbit lift when paired with an orbital-ring tether, and the backbone of a world cheap to supply from space.": ["地表から軌道へ伸びる索、すなわち軌道エレベーター。軌道環の索と組めば燃料なしで地表と軌道を往復でき、宇宙からの補給が安価な世界の基盤となる。", "從地面延伸至軌道的纜繩——太空電梯。與軌道環纜繩結合，地表與軌道之間的運輸無需燃料，是以低成本從太空補給一個世界的骨幹。", "从地面延伸至轨道的缆绳——太空电梯。与轨道环缆绳结合，地表与轨道之间的运输无需燃料，是以低成本从太空补给一个世界的骨干。"],
  "A tether to orbit: huge fuel-free LAUNCH capacity when paired with an orbital-ring tether above the world. Needs Orbital Tethers.": ["軌道への索。世界上空の軌道環の索と組めば、燃料なしで莫大な打ち上げ能力。軌道索が必要。", "通往軌道的纜繩：與世界上空的軌道環纜繩配對時，提供龐大的無燃料發射能力。需要軌道纜繩。", "通往轨道的缆绳：与世界上空的轨道环缆绳配对时，提供庞大的无燃料发射能力。需要轨道缆绳。"],
  "A varied grocery line from grains and livestock — more processed food per plant, on a bigger line.": ["穀物と家畜からの多彩な食品ライン。より大きなラインで工場あたりの加工食品が増える。", "以穀物與牲畜製作的多樣食品線——生產線更大，每座廠的加工食品更多。", "以谷物与牲畜制作的多样食品线——生产线更大，每座厂的加工食品更多。"],
  "A vast department generating far more bureaucratic capacity — at a far greater cost.": ["はるかに多くの官僚的能力を生む巨大な省庁。その代償もはるかに大きい。", "產生遠更多官僚產能的龐大部門——代價也遠更高。", "产生远更多官僚产能的庞大部门——代价也远更高。"],
  "A world held by an enemy army. It still belongs to its owner but produces nothing for them until liberated or ceded in a peace deal.": ["敵軍に保持された世界。所有者のものではあるが、解放されるか講和で割譲されるまで所有者に何も生まない。", "被敵軍佔據的世界。它仍屬原主，但在解放或於和約中割讓前不會為原主生產任何東西。", "被敌军占据的世界。它仍属原主，但在解放或于和约中割让前不会为原主生产任何东西。"],
  "A world your nation has settled. A Colony Ship founds one on a surveyed, unowned world, using its settlers (no Influence); it starts as a micro-colony.": ["自国が入植した世界。植民船が入植者を使い、調査済みで無主の世界に設立する(影響力不要)。微小植民地から始まる。", "本國已定居的世界。殖民船以其移民在已勘測、無主的世界建立（不需影響力）；初始為微型殖民地。", "本国已定居的世界。殖民船以其移民在已勘测、无主的世界建立（不需影响力）；初始为微型殖民地。"],
  "Actively suppressing and redirecting a hull's own heat signature.": ["船体自身の熱紋を能動的に抑え、逸らす技術。", "主動抑制並轉移艦體自身的熱訊號。", "主动抑制并转移舰体自身的热信号。"],
  "Adds glass and consumer fittings for finer furniture, on heavier tooling.": ["より重い工具で硝子と消費財の部品を加え、上質な家具に。", "加入玻璃與消費性配件，以更重的工具製作更精緻的家具。", "加入玻璃与消费性配件，以更重的工具制作更精致的家具。"],
  "Administrative capacity needed to run your buildings and territory.": ["建物と領土を運営するのに必要な行政能力。", "經營建築與領土所需的行政產能。", "经营建筑与领土所需的行政产能。"],
  "Air, water recycling and pressure housing. A pop's need for it is the world's unkindness: none on a fully habitable world, a heavy basic need on a barren rock or an aerostat.": ["空気、水の再循環、与圧住宅。必要量はその世界の過酷さ。完全に居住可能な世界ではゼロ、不毛の岩や浮遊都市では重い基礎需要。", "空氣、水回收與加壓住宅。人口對其需求取決於世界的嚴苛程度：完全宜居的世界為零，荒岩或浮空城則是沉重的基本需求。", "空气、水回收与加压住宅。人口对其需求取决于世界的严苛程度：完全宜居的世界为零，荒岩或浮空城则是沉重的基本需求。"],
  "Aircraft and orbital lift connect the world off-planet — balanced launch and interstellar freight capacity.": ["航空機と軌道揚力が世界を惑星外と結ぶ。打ち上げと恒星間貨物の能力の釣り合い。", "飛機與軌道升力將世界與外界相連——發射與星際貨運量兼顧。", "飞机与轨道升力将世界与外界相连——发射与星际货运量兼顾。"],
  "Aircraft from alloys, steel, engines, electronics and electrical machinery — lightweight airframes for spaceports and the wealthy.": ["合金、鋼、機関、電子機器、電気機械から航空機を作る。宇宙港と富裕層のための軽量機体。", "以合金、鋼、引擎、電子產品與電機製造飛機——供太空港與富人使用的輕量機身。", "以合金、钢、引擎、电子产品与电机制造飞机——供太空港与富人使用的轻量机身。"],
  "All money in the economy including bank deposits — much larger than base money, because banks lend deposits out again.": ["銀行預金を含む経済のすべてのお金。銀行が預金を再び貸すため、マネタリーベースよりずっと大きい。", "經濟中包含銀行存款在內的所有貨幣——因銀行會再把存款貸出，遠大於基礎貨幣。", "经济中包含银行存款在内的所有货币——因银行会再把存款贷出，远大于基础货币。"],
  "Alliances and bodies between nations.": ["国家間の同盟と機関。", "國家之間的同盟與組織。", "国家之间的同盟与组织。"],
  "Alloys, rocket fuel, precision machinery, explosives and electronics into rockets for spaceport-tier logistics — the boosters come fuelled.": ["合金、推進剤、精密機械、爆薬、電子機器から宇宙港級の物流用ロケットを作る。ブースターは燃料充填済み。", "以合金、火箭燃料、精密機械、炸藥與電子產品製造太空港等級物流用火箭——助推器出廠即已加注。", "以合金、火箭燃料、精密机械、炸药与电子产品制造太空港等级物流用火箭——助推器出厂即已加注。"],
  "Aluminium ore, titanium sands and lithium brine — the light metals, from one works.": ["アルミ鉱石、チタン砂、リチウム塩水。一つの工場から得る軽金属。", "鋁礦、鈦砂與鋰鹽水——同一工廠產出的輕金屬。", "铝矿、钛砂与锂盐水——同一工厂产出的轻金属。"],
  "An armed ship on patrol duty holds the orbit of the colony it circles. That is what turns a micro-colony into a planetary colony.": ["巡回任務中の武装艦は、周回する植民地の軌道を保持する。それが微小植民地を惑星植民地に変える。", "執行巡邏任務的武裝艦艇守住其環繞殖民地的軌道。正是這一點讓微型殖民地成為行星殖民地。", "执行巡逻任务的武装舰艇守住其环绕殖民地的轨道。正是这一点让微型殖民地成为行星殖民地。"],
  "An output multiplier from stability and your economy type.": ["安定と経済形態から来る産出倍率。", "來自穩定度與經濟類型的產出倍率。", "来自稳定度与经济类型的产出倍率。"],
  "Armed warships of nations at war with this world’s holder, orbiting it.": ["この世界の保持者と戦争中の国の武装艦で、軌道上にいるもの。", "與此世界持有者交戰之國家、正在其軌道上的武裝戰艦。", "与此世界持有者交战之国家、正在其轨道上的武装战舰。"],
  "Artists and craftspeople producing culture and art for a comfortable population.": ["芸術家と職人が、豊かな人々のために文化と芸術を生む。", "藝術家與工匠為生活寬裕的人們創作文化與藝術。", "艺术家与工匠为生活宽裕的人们创作文化与艺术。"],
  "Axes and saws. No power needed.": ["斧とのこぎり。電力不要。", "斧與鋸。無需電力。", "斧与锯。无需电力。"],
  "Banks, exchanges and brokerages. A lean overhead — the financial district earns its keep MANAGING the country's investment pool (a fee on the capital it stewards), not from this building.": ["銀行、取引所、証券会社。身軽な間接費。金融街はこの建物からではなく、国の投資資金を運用すること(管理する資本への手数料)で稼ぐ。", "銀行、交易所與經紀商。精簡的經常開支——金融區靠管理國家投資池（對所管資本收取費用）賺錢，而非靠這棟建築。", "银行、交易所与经纪商。精简的经常开支——金融区靠管理国家投资池（对所管资本收取费用）赚钱，而非靠这栋建筑。"],
  "Basic roads and utilities connecting the planet — modest infrastructure and freight capacity.": ["惑星を結ぶ基本的な道路と公共設備。控えめな社会基盤と貨物容量。", "連接行星的基本道路與公用設施——適度的基礎設施與貨運量。", "连接行星的基本道路与公用设施——适度的基础设施与货运量。"],
  "Blends copper, aluminium, nickel, titanium and lithium into high-performance alloys — the metal that ships, aircraft and vehicles are built from.": ["銅、アルミ、ニッケル、チタン、リチウムを高性能合金に配合する。艦、航空機、車両の素材となる金属。", "將銅、鋁、鎳、鈦與鋰調配成高性能合金——建造艦艇、飛機與車輛的金屬。", "将铜、铝、镍、钛与锂调配成高性能合金——建造舰艇、飞机与车辆的金属。"],
  "Blocks enemy landings nearby and absorbs most orbital bombardment while it stands.": ["立っている間、近くへの敵の上陸を阻み、軌道爆撃の大半を吸収する。", "存在期間阻擋附近的敵方登陸，並吸收大部分軌道轟炸。", "存在期间阻挡附近的敌方登陆，并吸收大部分轨道轰炸。"],
  "Breeds and stabilises hyperium from rare feedstock and vast power — the fuel a hyperdrive folds space with. Rarer and dearer than exotic matter; a handful a month from a whole plant.": ["希少な原料と莫大な電力から超空間鉱を育成し安定させる。超空間航法が空間を折る燃料。異種物質より希少で高価。工場一つで月に一握り。", "以稀有原料與龐大電力培育並穩定超空間礦——超空間引擎摺疊空間的燃料。比奇異物質更稀有昂貴；整座工廠每月僅產少許。", "以稀有原料与庞大电力培育并稳定超空间矿——超空间引擎折叠空间的燃料。比奇异物质更稀有昂贵；整座工厂每月仅产少许。"],
  "Build and repair ships in this system; capacity scales with the base tier.": ["この星系で艦を建造・修理する。能力は基地の段階に応じて増える。", "在此星系建造與修理艦艇；產能隨基地等級提升。", "在此星系建造与修理舰艇；产能随基地等级提升。"],
  "Building and holding station at real orbital scale, unmanned and unattended — the basis for a Starbase: a permanent claim on a system that needs no world to stand on.": ["実際の軌道規模で、無人のまま構造物を建設し位置を保つ技術。宇宙基地の基礎であり、立つべき世界を必要としない、星系への恒久的な権利主張となる。", "在真實軌道尺度上無人建造並維持站位——星際基地的基礎：無需立足之星即可對星系提出永久主張。", "在真实轨道尺度上无人建造并维持站位——星际基地的基础：无需立足之星即可对星系提出永久主张。"],
  "Building new buildings. Each project takes a set number of construction points; each can absorb at most 40 a month, so queue several to use them all.": ["新しい建物を建てること。各事業は決まった建設点を要し、一つが吸収できるのは月40まで。すべて使うには複数を予約する。", "建造新建築。每個工程需要一定建設點數；每項每月最多吸收40，因此要排入多項才能用盡。", "建造新建筑。每个工程需要一定建设点数；每项每月最多吸收40，因此要排入多项才能用尽。"],
  "Building the theory into hardware: field generators and exotic-matter handling small and robust enough to fit a ship. Every warp ship of the nation warps at this tier.": ["理論を装置へ。艦に収まるほど小さく頑丈な力場発生器と異種物質の取扱い。国のすべての歪曲艦がこの段階で航行する。", "將理論化為硬體：小巧堅固到能裝上艦艇的力場產生器與奇異物質處理設備。國家所有曲速艦皆以此等級航行。", "将理论化为硬件：小巧坚固到能装上舰艇的力场发生器与奇异物质处理设备。国家所有曲速舰皆以此等级航行。"],
  "Buildings clustered in the same district make each other more productive — shared suppliers, skills and infrastructure — and research parks lift the industry around them.": ["同じ区画に集まった建物は互いの生産性を高める(供給者、技能、社会基盤の共有)。研究団地は周りの工業を押し上げる。", "聚集在同一區劃的建築會相互提升生產力——共享供應商、技能與基礎設施——研究園區也會提升周邊工業。", "聚集在同一区划的建筑会相互提升生产力——共享供应商、技能与基础设施——研究园区也会提升周边工业。"],
  "Builds civilian spaceships — the freighters and liners that spaceports work to carry trade between worlds and nations.": ["民間宇宙船を建造する。宇宙港が世界と国の間の交易に使う貨物船と客船。", "建造民用太空船——太空港用來在世界與國家之間運送貿易的貨船與客輪。", "建造民用太空船——太空港用来在世界与国家之间运送贸易的货船与客轮。"],
  "Builds electronics from semiconductors, steel and electrical machinery.": ["半導体、鋼、電気機械から電子機器を作る。", "以半導體、鋼與電機製造電子產品。", "以半导体、钢与电机制造电子产品。"],
  "Builds engines from steel and machinery — the powerplant of vehicles and heavy machinery.": ["鋼と機械から機関を作る。車両と重機械の動力源。", "以鋼與機械製造引擎——車輛與重型機械的動力來源。", "以钢与机械制造引擎——车辆与重型机械的动力来源。"],
  "Builds the launch rockets that lift cargo from spaceports to orbit.": ["宇宙港から軌道へ貨物を打ち上げるロケットを建造する。", "建造將貨物從太空港送上軌道的運載火箭。", "建造将货物从太空港送上轨道的运载火箭。"],
  "Builds things: makes the construction points that raise new buildings and district levels. Burns minerals and energy.": ["物を建てる。新たな建物と区画段階を築く建設点を生む。鉱物と電力を消費する。", "負責建造：產生建造新建築與區劃等級的建設點數。消耗礦物與能源。", "负责建造：产生建造新建筑与区划等级的建设点数。消耗矿物与能源。"],
  "Burns coal for reliable bulk electricity, with water for cooling.": ["石炭を燃やして安定した大量の電力を生む。冷却に水を使う。", "燃燒煤炭提供穩定的大量電力，以水冷卻。", "燃烧煤炭提供稳定的大量电力，以水冷却。"],
  "Buying and selling goods with other markets.": ["他の市場と品を売買すること。", "與其他市場買賣商品。", "与其他市场买卖商品。"],
  "Capital-scale hulls with torpedo bays and the armour to survive a fleet action. Unlocks building the Battleship.": ["魚雷発射管と艦隊戦に耐える装甲を持つ主力艦級船体。戦艦の建造を解禁する。", "具備魚雷艙與足以撐過艦隊決戰之裝甲的主力艦級艦體。解鎖戰艦建造。", "具备鱼雷舱与足以撑过舰队决战之装甲的主力舰级舰体。解锁战舰建造。"],
  "Cash plus the reserves banks hold at the central bank — the money the central bank creates directly.": ["現金と、銀行が中央銀行に置く準備金。中央銀行が直接作るお金。", "現金加上銀行存放於央行的準備金——央行直接創造的貨幣。", "现金加上银行存放于央行的准备金——央行直接创造的货币。"],
  "Change what the map colours show (political, relations, …).": ["地図の色が示すものを変える(政治、関係、…)。", "改變地圖顏色所表示的內容（政治、關係…）。", "改变地图颜色所表示的内容（政治、关系…）。"],
  "Circuits and computers — used by research labs and fusion reactors, and wanted by specialists and workers.": ["回路と計算機。研究所と核融合炉で使われ、専門職と労働者も求める。", "電路與電腦——供研究室與核融合反應爐使用，專業人員與勞工也需要。", "电路与电脑——供研究室与核聚变反应堆使用，专业人员与劳工也需要。"],
  "Circuits and computers — used by research labs and wanted by the population.": ["回路と計算機。研究所で使われ、人々も求める。", "電路與電腦——供研究室使用，人民也需要。", "电路与电脑——供研究室使用，人民也需要。"],
  "Circuits, computers and sensors — consumed by research labs and wanted by the population. Produced only in Simple mode.": ["回路、計算機、探知器。研究所で消費され、人々も求める。簡易モードでのみ生産される。", "電路、電腦與感測器——研究室會消耗，人口也需要。僅在簡易模式中生產。", "电路、电脑与传感器——研究室会消耗，人口也需要。仅在简易模式中生产。"],
  "Civilian freighters and liners: the merchant fleet spaceports work. Built by spaceyards (Simple) or shipyards (Complex).": ["民間の貨物船と客船。宇宙港が運用する商船隊。宇宙造船所(簡易)か造船所(複雑)が建造する。", "民用貨船與客輪：太空港運用的商船隊。由太空船廠（簡易）或造船廠（複雜）建造。", "民用货船与客轮：太空港运用的商船队。由太空船厂（简易）或造船厂（复杂）建造。"],
  "Civilian freighters and liners: the merchant fleet that carries trade between worlds and nations, worked from spaceports.": ["民間の貨物船と客船。宇宙港を拠点に、世界と国の間で交易を運ぶ商船隊。", "民用貨船與客輪：以太空港為據點，在世界與國家之間運送貿易的商船隊。", "民用货船与客轮：以太空港为据点，在世界与国家之间运送贸易的商船队。"],
  "Civilian industries: the everyday goods every stratum wants. Short of them, people grow unhappy.": ["民生工業。どの階層も求める日用品。不足すれば人々は不満を募らせる。", "民用工業：各階層都需要的日用品。短缺時人民會不滿。", "民用工业：各阶层都需要的日用品。短缺时人民会不满。"],
  "Clean baseline power from sunlight — no fuel, modest output. Bootstraps the grid.": ["日光によるクリーンな基礎電力。燃料不要、出力は控えめ。電力網の立ち上げ役。", "來自陽光的潔淨基載電力——無需燃料，產出適中。電網的起步之源。", "来自阳光的洁净基载电力——无需燃料，产出适中。电网的起步之源。"],
  "Clerks and administrators producing the bureaucratic capacity the state runs on.": ["国家を動かす官僚的能力を生む事務員と行政官。", "產生國家運作所需官僚產能的文員與行政人員。", "产生国家运作所需官僚产能的文员与行政人员。"],
  "Clinics, entertainment and commerce — the amenities city life needs. Other nations’ embassies and branch offices are housed here too.": ["診療所、娯楽、商業。都市生活に必要な生活施設。他国の大使館と支店もここに入る。", "診所、娛樂與商業——城市生活所需的生活設施。他國的使館與分支機構也設於此。", "诊所、娱乐与商业——城市生活所需的生活设施。他国的使馆与分支机构也设于此。"],
  "Coal-free arc smelting — trades the blast furnace's mechanical plant for heavy electrical equipment (transformers, electrodes), on much more power.": ["石炭を使わない電炉製錬。高炉の機械設備を重電機器(変圧器、電極)に置き換え、はるかに多くの電力で動く。", "不用煤的電弧冶煉——以重型電氣設備（變壓器、電極）取代高爐的機械廠房，耗電遠更多。", "不用煤的电弧冶炼——以重型电气设备（变压器、电极）取代高炉的机械厂房，耗电远更多。"],
  "Coherent, focused beams of energy — the physics behind every laser and beam weapon in service.": ["収束したコヒーレントなエネルギー光線。あらゆるレーザーとビーム兵器の背後にある物理。", "相干、聚焦的能量光束——所有現役雷射與光束武器背後的物理。", "相干、聚焦的能量光束——所有现役激光与光束武器背后的物理。"],
  "Collects and treats surface water — rivers, lakes and reservoirs — into clean supply. Cheap to run, the backbone of a world's water.": ["河川、湖、貯水池の地表水を集めて浄化する。運営費が安く、世界の水の柱。", "收集並處理河川、湖泊與水庫的地表水，供應潔淨用水。營運成本低，是一個世界用水的支柱。", "收集并处理河流、湖泊与水库的地表水，供应洁净用水。运营成本低，是一个世界用水的支柱。"],
  "Combines phosphate and chemicals into fertilizer for farms.": ["燐と化学品を農場用の肥料に合成する。", "將磷礦與化學品合成為農用肥料。", "将磷矿与化学品合成为农用肥料。"],
  "Compact fusion plants and field generators for orbital bases: unlocks the Fusion Reactor and Shield Generator modules.": ["軌道基地用の小型核融合炉と力場発生器。核融合炉と遮蔽発生器の区画を解禁する。", "供軌道基地使用的小型核融合發電廠與力場產生器：解鎖核融合反應爐與護盾產生器模組。", "供轨道基地使用的小型核聚变电厂与力场发生器：解锁核聚变反应堆与护盾发生器模组。"],
  "Companies that own buildings, earn profits and pay dividends to their owners.": ["建物を所有し、利益を上げ、所有者に配当を払う会社。", "擁有建築、賺取利潤並向所有者支付股息的公司。", "拥有建筑、赚取利润并向所有者支付股息的公司。"],
  "Complex mode: cloth and clothing, woven from wool and synthetic fibre and coloured with dyes. People buy them as everyday clothing; furniture and luxury makers use some.": ["複雑モード：羊毛と合成繊維を織り染料で染めた布と衣服。人々が日常の衣料として買い、家具と奢侈品の製造者も一部使う。", "複雜模式：以羊毛與合成纖維織成、用染料著色的布料與衣物。人民作為日常衣著購買；家具與奢侈品製造商也會使用一些。", "复杂模式：以羊毛与合成纤维织成、用染料着色的布料与衣物。人民作为日常衣着购买；家具与奢侈品制造商也会使用一些。"],
  "Complex mode: harbours on worlds with seas — they work ocean-going ships and fuel into infrastructure and freight capacity.": ["複雑モード：海のある世界の港。外航船と燃料を社会基盤と貨物容量に変える。", "複雜模式：有海世界的港口——將遠洋船與燃料轉為基礎設施與貨運量。", "复杂模式：有海世界的港口——将远洋船与燃料转为基础设施与货运量。"],
  "Complex mode: how well pops live — how much of their needs they can afford. Food, water, clothes and a roof (the basic and everyday needs) lift it only to about one half; healthcare, comfort and luxury carry the rest. Quality of life is shown beside it, not inside it.": ["複雑モード：人々の暮らし向き。必要をどれだけ賄えるか。食料、水、衣服、屋根(基礎と日常の需要)は半分ほどまでしか上げず、残りは医療、快適さ、贅沢が担う。生活の質はその中ではなく横に示される。", "複雜模式：人口生活得多好——能負擔多少需求。食物、水、衣物與住所（基本與日常需求）只能提升到約一半；其餘靠醫療、舒適與奢侈。生活品質顯示在其旁，不包含在內。", "复杂模式：人口生活得多好——能负担多少需求。食物、水、衣物与住所（基本与日常需求）只能提升到约一半；其余靠医疗、舒适与奢侈。生活质量显示在其旁，不包含在内。"],
  "Complex mode: the share of a building’s capacity standing idle — kept, not demolished. It reopens bit by bit when its good runs short, and owners mothball more of a plant whose good piles up unsold.": ["複雑モード：建物の能力のうち遊休の割合。取り壊さず保持される。その品が不足すると少しずつ再開し、売れ残る品の工場は所有者がさらに休止させる。", "複雜模式：建築產能中閒置的比例——保留而非拆除。當其貨品短缺時逐步重啟，貨品滯銷時所有者會封存更多產能。", "复杂模式：建筑产能中闲置的比例——保留而非拆除。当其货品短缺时逐步重启，货品滞销时所有者会封存更多产能。"],
  "Compressing gas-giant hydrogen into metastable metallic hydrogen — a vast, clean source of rocket fuel skimmed straight from the clouds of a gas giant. Unlocks the Metallic Hydrogen Plant.": ["巨大ガス惑星の水素を圧縮し、準安定な金属水素に変える。ガス惑星の雲から直接すくい取れる、膨大でクリーンなロケット燃料源。金属水素工場を解禁する。", "將氣態巨行星的氫壓縮為亞穩態金屬氫——直接從氣態巨行星雲層汲取的龐大潔淨火箭燃料來源。解鎖金屬氫廠。", "将气态巨行星的氢压缩为亚稳态金属氢——直接从气态巨行星云层汲取的庞大洁净火箭燃料来源。解锁金属氢厂。"],
  "Computation exploiting superposition and entanglement — a real leap in processing efficiency.": ["重ね合わせともつれを利用する計算。処理効率の本物の飛躍。", "利用疊加與糾纏的運算——處理效率的真正飛躍。", "利用叠加与纠缠的运算——处理效率的真正飞跃。"],
  "Condenses and holds exotic matter in magnetic-confinement lattices — the stuff that threads a warp field. Enormous power for a trickle of output; the feedstock of every warp drive.": ["磁気閉じ込め格子で異種物質を凝縮し保持する。歪曲場を通す物質。わずかな産出に莫大な電力。あらゆる歪曲航法の原料。", "以磁約束晶格凝聚並保存奇異物質——編織曲速場的材料。消耗龐大電力卻僅有涓滴產出；每具曲速引擎的原料。", "以磁约束晶格凝聚并保存奇异物质——编织曲速场的材料。消耗庞大电力却仅有涓滴产出；每具曲速引擎的原料。"],
  "Continuous stationkeeping thrust, precisely countering a body's gravity well. A ship can hold any position it chooses instead of settling into a natural orbit — at the real cost, in reaction mass and power, of fighting gravity every second it does.": ["天体の重力井戸を正確に打ち消す持続的な位置保持推力。艦は自然な軌道に落ち着く代わりに任意の位置を保持できるが、その間ずっと重力と戦うため、推進剤と電力という現実の代償を払う。", "持續的定位推力，精確抵銷天體的重力井。艦艇可停留在任意選定位置，而非落入自然軌道——代價是每一秒都在對抗重力，消耗推進劑與電力。", "持续的定位推力，精确抵消天体的重力井。舰艇可停留在任意选定位置，而非落入自然轨道——代价是每一秒都在对抗重力，消耗推进剂与电力。"],
  "Contractors, cranes and crews. Produces the construction capacity that builds everything on this world — build more to build faster. Consumes some upkeep; the bulk materials are consumed by the projects themselves.": ["請負業者、クレーン、作業班。この世界のあらゆるものを建てる建設能力を生む。増やすほど速く建つ。多少の維持費を使い、大量の資材は各事業自体が消費する。", "承包商、起重機與施工隊。產生建造此世界一切的建設產能——建得越多，蓋得越快。需少量維護；大宗材料由各工程本身消耗。", "承包商、起重机与施工队。产生建造此世界一切的建设产能——建得越多，盖得越快。需少量维护；大宗材料由各工程本身消耗。"],
  "Controlled, gradual extraction from an exotic matter deposit, rather than an uncontrolled release.": ["異種物質鉱床から、制御されない放出ではなく、制御された段階的な採取を行う技術。", "從奇異物質礦藏中受控、漸進地開採，而非失控釋放。", "从奇异物质矿藏中受控、渐进地开采，而非失控释放。"],
  "Copper and nickel from open-pit ore — the base metals, as co-products of one mine.": ["露天掘りの鉱石から銅とニッケル。一つの鉱山の副産物としての卑金属。", "從露天礦石取得銅與鎳——同一礦場共生的基本金屬。", "从露天矿石取得铜与镍——同一矿场共生的基本金属。"],
  "Covering a deficit by creating new money instead of borrowing. Quick and debt-free, but more money chasing the same goods means inflation.": ["借入でなく新しいお金を作って赤字を埋めること。速くて債務もないが、同じ品をより多くのお金が追えば物価が上がる。", "以創造新貨幣而非借款來填補赤字。快速且不增加債務，但更多貨幣追逐同樣的商品就會造成通膨。", "以创造新货币而非借款来填补赤字。快速且不增加债务，但更多货币追逐同样的商品就会造成通胀。"],
  "Cracks oil into industrial chemicals in machinery-driven plant, with process water.": ["機械駆動の工場で原油を工業化学品に分解する。工程水を使う。", "在機械驅動的廠房中以製程用水將石油裂解為工業化學品。", "在机械驱动的厂房中以工艺用水将石油裂解为工业化学品。"],
  "Cuts timber into lumber on powered saws.": ["動力のこぎりで原木を製材にする。", "以動力鋸將原木切成木材。", "以动力锯将原木切成木材。"],
  "Cutting machines lift output sharply on grid power and mining machinery.": ["切羽採炭機が電力と採掘機械で産出を大きく高める。", "採煤機以電網電力與採礦機械大幅提升產量。", "采煤机以电网电力与采矿机械大幅提升产量。"],
  "Damage from orbital bombardment. It cuts a world’s output by up to half and heals slowly once the bombing stops.": ["軌道爆撃による損害。世界の産出を最大半分削り、爆撃が止むとゆっくり回復する。", "軌道轟炸造成的損害。最多削減世界一半產出，轟炸停止後緩慢恢復。", "轨道轰炸造成的损害。最多削减世界一半产出，轰炸停止后缓慢恢复。"],
  "Deflector fields — a standing electromagnetic barrier that absorbs incoming energy before it reaches the hull.": ["偏向場。到達前に入射エネルギーを吸収する、常在の電磁障壁。", "偏導力場——在能量抵達艦體前將其吸收的常駐電磁屏障。", "偏导力场——在能量抵达舰体前将其吸收的常驻电磁屏障。"],
  "Directly editing genetic code — hardier colonists and crops engineered for conditions Earth life never evolved for.": ["遺伝暗号を直接編集する技術。地球の生命が適応したことのない環境に合わせて設計された、より頑健な入植者と作物。", "直接編輯遺傳密碼——為地球生命從未演化過的環境而設計的更強韌殖民者與作物。", "直接编辑遗传密码——为地球生命从未演化过的环境而设计的更强韧殖民者与作物。"],
  "Docks and ocean-going ships carry freight along a world’s coasts and across its seas — strong infrastructure and freight capacity, on a world with sea.": ["港と外航船が世界の沿岸と海を越えて貨物を運ぶ。海のある世界での強力な社会基盤と貨物容量。", "碼頭與遠洋船沿著世界海岸與跨越海洋運送貨物——在有海的世界提供強大的基礎設施與貨運量。", "码头与远洋船沿着世界海岸与跨越海洋运送货物——在有海的世界提供强大的基础设施与货运量。"],
  "Drawing exotic matter from the few, small deposits some worlds near Sol hold: draws exotic matter from the deposits on bodies the nation owns, until they run dry.": ["太陽近傍のいくつかの世界にある少数の小さな鉱床から異種物質を採る。国が所有する天体の鉱床から、枯渇するまで採取する。", "從太陽附近部分星球上少數小型礦藏汲取奇異物質：從本國擁有之天體的礦藏開採，直到枯竭。", "从太阳附近部分星球上少数小型矿藏汲取奇异物质：从本国拥有之天体的矿藏开采，直到枯竭。"],
  "Drills and haulers double output, running on power and tools.": ["掘削機と運搬車で産出が倍に。電力と工具で動く。", "鑽機與運輸車讓產量加倍，需電力與工具。", "钻机与运输车让产量加倍，需电力与工具。"],
  "Each card is a place on {0}. Press + Build here on any of yours: the district it needs is developed for you.": ["各カードは{0}上の場所です。自分のカードで「ここに建設」を押すと、必要な地区が自動的に開発されます。", "每張卡片都是{0}上的一個地點。在你的任何地點按「在此建造」，所需的區域會自動為你開發。", "每张卡片都是{0}上的一个地点。在你的任何地点按“在此建造”，所需的区域会自动为你开发。"],
  "Each card is a place on {0}. Press + Build here on any of yours: the district it needs is developed for you. Room for {1} more district level on this world.": ["各カードは{0}上の場所です。自分のカードで「ここに建設」を押すと、必要な地区が自動的に開発されます。この世界にはあと{1}地区レベル分の余地があります。", "每張卡片都是{0}上的一個地點。在你的任何地點按「在此建造」，所需的區域會自動為你開發。這個世界還有{1}個區域等級的空間。", "每张卡片都是{0}上的一个地点。在你的任何地点按“在此建造”，所需的区域会自动为你开发。这个世界还有{1}个区域等级的空间。"],
  "Each card is a place on {0}. Press + Build here on any of yours: the district it needs is developed for you. Room for {1} more district levels on this world.": ["各カードは{0}上の場所です。自分のカードで「ここに建設」を押すと、必要な地区が自動的に開発されます。この世界にはあと{1}地区レベル分の余地があります。", "每張卡片都是{0}上的一個地點。在你的任何地點按「在此建造」，所需的區域會自動為你開發。這個世界還有{1}個區域等級的空間。", "每张卡片都是{0}上的一个地点。在你的任何地点按“在此建造”，所需的区域会自动为你开发。这个世界还有{1}个区域等级的空间。"],
  "Economists, sociologists and policy scholars studying how societies work — the strongest single source of Society research.": ["社会の仕組みを研究する経済学者、社会学者、政策研究者。社会研究の最強の単一源。", "研究社會如何運作的經濟學家、社會學家與政策學者——最強的單一社會研究來源。", "研究社会如何运作的经济学家、社会学家与政策学者——最强的单一社会研究来源。"],
  "Educators providing schooling — raises the population it serves.": ["教育を提供する教育者。担当する人口を向上させる。", "提供教育的教師——提升其服務的人口。", "提供教育的教师——提升其服务的人口。"],
  "Efficient heat dissipation and recapture. Exotic matter's output is effectively infinite, but only as much of it as doesn't leak away as waste heat is actually usable.": ["効率的な放熱と熱回収。異種物質の出力は事実上無限だが、実際に使えるのは廃熱として漏れ出さなかった分だけである。", "高效散熱與熱回收。奇異物質的輸出實際上無窮無盡，但真正可用的只有未以廢熱散失的那一部分。", "高效散热与热回收。奇异物质的输出实际上无穷无尽，但真正可用的只有未以废热散失的那一部分。"],
  "Electrolysis and powered processing raise the yield of all three light metals, on heavy power.": ["電気分解と動力処理で三種の軽金属すべての収量が上がる。大電力が要る。", "電解與動力處理提升三種輕金屬的產量，耗電量大。", "电解与动力处理提升三种轻金属的产量，耗电量大。"],
  "Electronics and consumer goods into luxuries for the wealthy.": ["電子機器と消費財から富裕層向けの奢侈品を作る。", "以電子產品與消費品為富人製作奢侈品。", "以电子产品与消费品为富人制作奢侈品。"],
  "Electronics and power running the online services pops and businesses rely on.": ["人々と企業が頼る通信網サービスを、電子機器と電力で運営する。", "以電子產品與電力運行人民與企業所依賴的網路服務。", "以电子产品与电力运行人民与企业所依赖的网络服务。"],
  "Emergency wartime taxes: more revenue, but people resent them — a standing hit to happiness/stability.": ["戦時の臨時税。歳入は増えるが、人々は反発し、幸福度・安定が常に下がる。", "戰時緊急稅：收入增加，但人民不滿——持續打擊幸福度與穩定。", "战时紧急税：收入增加，但人民不满——持续打击幸福度与稳定。"],
  "Energy barrier that absorbs damage first and recharges.": ["最初に損害を吸収し、再充電されるエネルギー障壁。", "率先吸收傷害並會自行充能的能量屏障。", "率先吸收伤害并会自行充能的能量屏障。"],
  "Energy release from nuclear reactions — a real efficiency gain over chemical or purely electromagnetic power.": ["核反応によるエネルギー放出。化学的・純電磁的な電力を上回る本物の効率向上。", "核反應釋放的能量——相較化學或純電磁電力的實質效率提升。", "核反应释放的能量——相较化学或纯电磁电力的实质效率提升。"],
  "Enormous clean output from rare metals and electrical machinery, with coolant water — but a specialist workforce.": ["希少金属と電気機械、冷却水から莫大でクリーンな出力を生む。ただし専門職の労働力が要る。", "以稀有金屬與電機、冷卻水產生龐大潔淨電力——但需要專業人員。", "以稀有金属与电机、冷却水产生庞大洁净电力——但需要专业人员。"],
  "Entangled hyperspace relays — a message departs and arrives in the same instant, anywhere. The end of the light-speed leash on command.": ["もつれた超空間中継。どこであれ、通信は出発と同時に到着する。指揮を縛る光速の鎖の終わり。", "糾纏的超空間中繼——訊息在出發的同一瞬間抵達任何地方。指揮不再受光速束縛。", "纠缠的超空间中继——信息在出发的同一瞬间抵达任何地方。指挥不再受光速束缚。"],
  "Etches rare metals and chemicals into semiconductors — power-hungry, specialist, machinery-intensive.": ["希少金属と化学品から半導体を焼き付ける。電力を食い、専門的で、機械集約的。", "以稀有金屬與化學品蝕刻製成半導體——耗電、專業、機械密集。", "以稀有金属与化学品蚀刻制成半导体——耗电、专业、机械密集。"],
  "Everyday manufactured products people want — shortages make them unhappy.": ["人々が求める日用の工業製品。不足すると不満を抱く。", "人民想要的日常工業製品——短缺使他們不快樂。", "人民想要的日常工业制品——短缺使他们不快乐。"],
  "Everything the state owes from past borrowing. It costs interest every year; too much of it hurts the credit rating.": ["過去の借入で国が負うすべて。毎年利息がかかり、多すぎると信用格付を損なう。", "國家過去借款所欠的一切。每年需付利息；過多會損害信用評級。", "国家过去借款所欠的一切。每年需付利息；过多会损害信用评级。"],
  "Exports minus imports. A surplus earns money and strengthens the currency; a deficit does the opposite.": ["輸出から輸入を引いたもの。黒字はお金を稼ぎ通貨を強め、赤字は逆。", "出口減去進口。順差賺錢並強化貨幣；逆差則相反。", "出口减去进口。顺差赚钱并强化货币；逆差则相反。"],
  "Extracts minerals — the raw input for industry and construction.": ["鉱物を採掘する。工業と建設の原料。", "開採礦物——工業與建設的原料。", "开采矿物——工业与建设的原料。"],
  "Extremely rare fuel for hyperdrives. Drawn from finite natural deposits on a few worlds near Sol, or refined from exotic matter once Hyperium Synthesis is researched.": ["超空間航法の極めて希少な燃料。太陽近傍の少数の世界の有限な天然鉱床から採るか、超空間鉱合成を研究すれば異種物質から精製できる。", "超空間引擎極稀有的燃料。取自太陽附近少數世界的有限天然礦藏，或在研究超空間礦合成後由奇異物質精煉。", "超空间引擎极稀有的燃料。取自太阳附近少数世界的有限天然矿藏，或在研究超空间矿合成后由奇异物质精炼。"],
  "Extremely rare, yields effectively infinite energy, and can't be subdivided — fuels hyperdrives, making every hyperdrive-equipped hull valuable in its own right.": ["極めて希少で、事実上無限のエネルギーを生み、分割できない。超空間航法の燃料であり、超空間機関を積む船体はそれだけで価値がある。", "極其稀有，能產生近乎無限的能量，且無法分割——超空間引擎的燃料，使每艘配備超空間引擎的艦體本身就價值不菲。", "极其稀有，能产生近乎无限的能量，且无法分割——超空间引擎的燃料，使每艘配备超空间引擎的舰体本身就价值不菲。"],
  "Factories, foundries and refineries. Every building here makes the others more productive (suppliers, skilled labour, shared logistics), and research parks nearby boost it further.": ["工場、鋳造所、精製所。ここの建物は互いの生産性を高め(供給者、熟練労働、物流の共有)、近くの研究団地がさらに押し上げる。", "工廠、鑄造廠與精煉廠。此處每座建築都讓其他建築更具生產力（供應商、熟練勞工、共享物流），附近的研究園區更能進一步提升。", "工厂、铸造厂与精炼厂。此处每座建筑都让其他建筑更具生产力（供应商、熟练劳工、共享物流），附近的研究园区更能进一步提升。"],
  "Falling prices. Sounds nice, but it usually means demand has collapsed and makes debts heavier.": ["物価の下落。聞こえは良いが、たいていは需要の崩壊を意味し、債務を重くする。", "物價下跌。聽來不錯，但通常意味著需求崩潰，並加重債務。", "物价下跌。听来不错，但通常意味着需求崩溃，并加重债务。"],
  "Farmland, hydroponics and food processing. Farms here share irrigation, storage and markets.": ["農地、水耕、食品加工。ここの農場は灌漑、貯蔵、市場を共有する。", "農田、水耕與食品加工。此處農場共享灌溉、倉儲與市場。", "农田、水耕与食品加工。此处农场共享灌溉、仓储与市场。"],
  "Fast escort hulls with room for a dense point-defense fit. Unlocks building the Destroyer.": ["近接防御を密に積める高速護衛船体。駆逐艦の建造を解禁する。", "可密集裝載點防禦的高速護航艦體。解鎖驅逐艦建造。", "可密集装载点防御的高速护航舰体。解锁驱逐舰建造。"],
  "Fast-tracking, short-range interception fire, purpose-built to shoot down incoming missiles and torpedoes.": ["飛来する誘導弾と魚雷を撃ち落とすために作られた、高速追尾の短距離迎撃射撃。", "專為擊落來襲飛彈與魚雷而設計的高速追蹤短程攔截火力。", "专为击落来袭导弹与鱼雷而设计的高速追踪短程拦截火力。"],
  "Feedlots and powered handling raise more stock on more feed.": ["肥育場と動力化された取扱いで、より多くの飼料からより多くの家畜を育てる。", "育肥場與動力化處理，以更多飼料養出更多牲畜。", "育肥场与动力化处理，以更多饲料养出更多牲畜。"],
  "Feeds a population. A sustained shortage starves colonies; a surplus supports growth.": ["人口を養う。長く不足すれば植民地は飢え、余れば成長を支える。", "養活人口。長期短缺會讓殖民地挨餓；有餘則支撐成長。", "养活人口。长期短缺会让殖民地挨饿；有余则支撑增长。"],
  "Fertilizer, tools and power lift the cane yield.": ["肥料、工具、電力でサトウキビの収量が上がる。", "肥料、工具與電力提高甘蔗產量。", "肥料、工具与电力提高甘蔗产量。"],
  "Fertilizer, tools and power raise coffee yields.": ["肥料、工具、電力で珈琲の収量が上がる。", "肥料、工具與電力提高咖啡產量。", "肥料、工具与电力提高咖啡产量。"],
  "Fertilizer, tools and power raise tea yields.": ["肥料、工具、電力で茶の収量が上がる。", "肥料、工具與電力提高茶葉產量。", "肥料、工具与电力提高茶叶产量。"],
  "Fertilizer, tools, flood water and pumps lift yields.": ["肥料、工具、灌漑水、ポンプで収量が上がる。", "肥料、工具、灌溉水與水泵提升產量。", "肥料、工具、灌溉水与水泵提升产量。"],
  "Fertilizer, tools, water and power raise yields with fewer, more skilled hands.": ["肥料、工具、水、電力で、少数の熟練した手で収量を上げる。", "肥料、工具、水與電力，以更少但更熟練的人手提高收成。", "肥料、工具、水与电力，以更少但更熟练的人手提高收成。"],
  "Fights you are in right now, in space and on the ground. Click one to open it.": ["今まさに参加している宇宙と地上の戦い。クリックで開く。", "你正在參與的太空與地面戰鬥。點擊即可開啟。", "你正在参与的太空与地面战斗。点击即可打开。"],
  "Fires coal-heated kilns to produce cement and concrete — the bulk material almost every construction consumes.": ["石炭焚きの窯でセメントとコンクリートを作る。ほぼすべての建設が消費するバルク資材。", "以燃煤窯爐生產水泥與混凝土——幾乎所有建設都會消耗的大宗材料。", "以燃煤窑炉生产水泥与混凝土——几乎所有建设都会消耗的大宗材料。"],
  "Foreign currency the central bank holds, used to defend its own currency's value.": ["中央銀行が持つ外貨。自国通貨の価値を守るのに使う。", "央行持有的外國貨幣，用於捍衛本國貨幣的價值。", "央行持有的外国货币，用于捍卫本国货币的价值。"],
  "Foreign exchange — the market where currencies are traded against each other.": ["外国為替。通貨同士が取引される市場。", "外匯——各種貨幣相互交易的市場。", "外汇——各种货币相互交易的市场。"],
  "Forms steel into the tools nearly every industry and mechanized worker runs on.": ["鋼をほぼすべての産業と機械化労働者が使う工具に成形する。", "將鋼鍛造成幾乎所有產業與機械化勞工所依賴的工具。", "将钢锻造成几乎所有产业与机械化劳工所依赖的工具。"],
  "Fortresses, shield generators and defense batteries — the world’s planetary defenses. Each takes one slot while it stands; build them here or from the Defense tab.": ["要塞、遮蔽発生器、防衛砲台。世界の惑星防衛。立っている間それぞれ一枠を使う。ここか防衛タブから建てる。", "要塞、護盾產生器與防禦砲台——世界的行星防禦。存在期間各佔一格；可在此或在防禦分頁建造。", "要塞、护盾发生器与防御炮台——世界的行星防御。存在期间各占一格；可在此或在防御分页建造。"],
  "Fortresses, shield generators and defense batteries on a world’s surface. They serve whoever holds the ground they stand on — so they can be captured — and can be destroyed.": ["世界の地表の要塞、遮蔽発生器、防衛砲台。立つ地面を握る者に仕えるので奪取されうるし、破壊もされる。", "世界地表上的要塞、護盾產生器與防禦砲台。它們為控制其所在地面的一方效力——因此可被奪取——也可被摧毀。", "世界地表上的要塞、护盾发生器与防御炮台。它们为控制其所在地面的一方效力——因此可被夺取——也可被摧毁。"],
  "FTL signal relays, riding the same exotic-matter warp field a warp drive does — order and report transit times measured in days rather than years.": ["歪曲航法と同じ異種物質の歪曲場に乗る超光速通信中継。命令と報告の伝達時間は年ではなく日で測られる。", "乘著與曲速引擎相同之奇異物質曲速場的超光速訊號中繼——命令與報告的傳遞時間以日而非年計。", "乘着与曲速引擎相同之奇异物质曲速场的超光速信号中继——命令与报告的传递时间以日而非年计。"],
  "Game options.": ["ゲームの設定。", "遊戲選項。", "游戏选项。"],
  "GDP measured in starting prices, with inflation stripped out. It only grows when the nation actually produces more.": ["開始時の価格で測り、物価上昇を除いたGDP。国が実際により多く生産したときだけ増える。", "以起始價格計算、扣除通膨的GDP。只有國家實際生產更多時才會成長。", "以起始价格计算、扣除通胀的GDP。只有国家实际生产更多时才会增长。"],
  "Generates energy for industry, labs, refineries and ships.": ["工業、研究所、精製所、艦のための電力を生む。", "為工業、研究室、精煉廠與艦艇發電。", "为工业、研究室、精炼厂与舰艇发电。"],
  "Goods bought from abroad.": ["国外から買う品。", "從國外購買的商品。", "从国外购买的商品。"],
  "Goods in storage. Ships, armies, industry and people all draw from it.": ["保管中の品。艦、軍、工業、人々のすべてがここから引き出す。", "庫存中的貨品。艦艇、軍隊、工業與人民都從中取用。", "库存中的货品。舰艇、军队、工业与人民都从中取用。"],
  "Goods sold abroad.": ["国外へ売る品。", "賣往國外的商品。", "卖往国外的商品。"],
  "Gross domestic product — the value of everything a nation produces in a year. The main measure of how big an economy is. 'Nominal' GDP is measured in today's prices, so inflation alone makes it grow.": ["国内総生産。国が一年に生み出すすべての価値。経済規模の主な尺度。「名目」GDPは今の価格で測るため、物価上昇だけでも増える。", "國內生產毛額——一個國家一年內生產的全部價值。衡量經濟規模的主要指標。「名目」GDP以當前價格計算，因此光是通膨就會使其成長。", "国内生产总值——一个国家一年内生产的全部价值。衡量经济规模的主要指标。“名义”GDP以当前价格计算，因此光是通胀就会使其增长。"],
  "Ground forces — they garrison worlds and invade enemy ones.": ["地上部隊。世界を守備し、敵の世界に侵攻する。", "地面部隊——駐守世界並入侵敵方世界。", "地面部队——驻守世界并入侵敌方世界。"],
  "Groups of people who work, earn, consume and hold political views.": ["働き、稼ぎ、消費し、政治的見解を持つ人々の集団。", "工作、賺錢、消費並持有政治觀點的人群。", "工作、赚钱、消费并持有政治观点的人群。"],
  "Grows food for the population.": ["人々のために食料を育てる。", "為人口種植糧食。", "为人口种植粮食。"],
  "Guns that return fire on warships besieging the base, and extra armour.": ["基地を包囲する軍艦に反撃する砲と、追加装甲。", "向圍攻基地之戰艦還擊的火砲，以及額外裝甲。", "向围攻基地之战舰还击的火炮，以及额外装甲。"],
  "Hand-cut sugarcane. Labor-heavy, no inputs.": ["手で刈るサトウキビ。労働集約的で投入不要。", "手工收割甘蔗。勞力密集，無需投入。", "手工收割甘蔗。劳力密集，无需投入。"],
  "Hand-felled hardwood from a separate, slower-growing stand than the timber camps. No power needed.": ["木材伐採所とは別の、成長の遅い林から手で伐る硬材。電力不要。", "從生長較慢、與木材營地分開的林地手工伐取硬木。無需電力。", "从生长较慢、与木材营地分开的林地手工伐取硬木。无需电力。"],
  "Hand-picked coffee cherries. Labor-heavy, no inputs.": ["手摘みの珈琲の実。労働集約的で投入不要。", "手工採摘咖啡果。勞力密集，無需投入。", "手工采摘咖啡果。劳力密集，无需投入。"],
  "Hand-picked tea leaf. Labor-heavy, no inputs.": ["手摘みの茶葉。労働集約的で投入不要。", "手工採摘茶葉。勞力密集，無需投入。", "手工采摘茶叶。劳力密集，无需投入。"],
  "Hands and simple tools. Employs many, needs no inputs.": ["手と簡単な道具。多くを雇い、投入は不要。", "人手與簡單工具。僱用眾多人力，無需投入。", "人手与简单工具。雇用众多人力，无需投入。"],
  "Healthcare: provides amenities and makes the population grow faster.": ["医療。生活施設を提供し、人口の増加を早める。", "醫療：提供生活設施並加快人口成長。", "医疗：提供生活设施并加快人口增长。"],
  "Heavy rocketry maximises surface↔orbit LAUNCH capacity at the cost of interstellar freight.": ["重ロケットで地表と軌道間の打ち上げ能力を最大化する。恒星間貨物は犠牲になる。", "重型火箭將地表與軌道間的發射量最大化，代價是星際貨運量。", "重型火箭将地表与轨道间的发射量最大化，代价是星际货运量。"],
  "Heavy rolling stock from steel, alloys, engines and heavy machinery — the backbone of railways.": ["鋼、合金、機関、重機械から重い車両を作る。鉄道の柱。", "以鋼、合金、引擎與重型機械製造重型車輛——鐵路的骨幹。", "以钢、合金、引擎与重型机械制造重型车辆——铁路的骨干。"],
  "Herds fed on feed grain, tended by hand.": ["飼料穀物で育て、手で世話する家畜の群れ。", "以飼料穀物餵養、人工照料的畜群。", "以饲料谷物喂养、人工照料的畜群。"],
  "High-tolerance instruments and machine tools from electrical machinery, electronics and rare metals — for the most advanced industry.": ["電気機械、電子機器、希少金属から高精度の計器と工作機械。最先端の産業のために。", "以電機、電子產品與稀有金屬製造高精度儀器與工具機——供最先進的產業使用。", "以电机、电子产品与稀有金属制造高精度仪器与工具机——供最先进的产业使用。"],
  "How content a group of people is (0–100%). Shortages, unemployment, inflation and war taxes lower it; welfare raises it.": ["集団の満足度(0〜100%)。不足、失業、物価上昇、戦時税で下がり、福祉で上がる。", "一群人的滿足程度（0–100%）。短缺、失業、通膨與戰爭稅使其下降；福利使其上升。", "一群人的满足程度（0–100%）。短缺、失业、通胀与战争税使其下降；福利使其上升。"],
  "How expensive things are compared to the start of the game (1.00). It rises with inflation.": ["開始時(1.00)と比べた物価の高さ。物価上昇とともに上がる。", "與遊戲開始時（1.00）相比的物價高低。隨通膨上升。", "与游戏开始时（1.00）相比的物价高低。随通胀上升。"],
  "How far the economy is running above or below its normal capacity. Above capacity tends to push inflation up; below means idle resources.": ["経済が通常の能力をどれだけ上回る・下回るか。上回れば物価を押し上げやすく、下回れば資源が遊ぶ。", "經濟運行高於或低於正常產能的程度。高於產能易推升通膨；低於則代表資源閒置。", "经济运行高于或低于正常产能的程度。高于产能易推升通胀；低于则代表资源闲置。"],
  "How fast GDP is growing in current prices — real growth plus inflation.": ["現在価格でのGDPの成長率。実質成長に物価上昇を足したもの。", "以當前價格計算的GDP成長率——實質成長加上通膨。", "以当前价格计算的GDP增长率——实际增长加上通胀。"],
  "How fast prices are rising, per year. A little (around 2%) is normal. High inflation makes people unhappy, erodes savings and weakens the currency. Printing money to cover a deficit is the usual cause.": ["物価の年間上昇率。少し(2%前後)は普通。高い物価上昇は人々を不満にし、貯蓄を目減りさせ、通貨を弱める。赤字を紙幣発行で賄うのがよくある原因。", "物價每年上漲的速度。少許（約2%）屬正常。高通膨使人民不滿、侵蝕儲蓄並削弱貨幣。以印鈔填補赤字是常見原因。", "物价每年上涨的速度。少许（约2%）属正常。高通胀使人民不满、侵蚀储蓄并削弱货币。以印钞填补赤字是常见原因。"],
  "How fast real GDP is growing, per year. Positive means the economy is really getting bigger; negative is a recession.": ["実質GDPの年間成長率。正なら経済は本当に大きくなっている。負なら景気後退。", "實質GDP的年成長率。為正代表經濟真正擴大；為負則是衰退。", "实际GDP的年增长率。为正代表经济真正扩大；为负则是衰退。"],
  "How kind the surface is to its people. A hostile world makes its people spend on life support (air, water, pressure housing) just to stay alive, and costs a little standard of living.": ["地表が住民にどれだけ優しいか。過酷な世界では生きるためだけに生命維持(空気、水、与圧住宅)に支出し、生活水準も少し下がる。", "地表對居民有多友善。嚴苛的世界讓居民光為活命就得花錢在維生（空氣、水、加壓住宅）上，也會稍降生活水準。", "地表对居民有多友善。严苛的世界让居民光为活命就得花钱在维生（空气、水、加压住宅）上，也会稍降生活水平。"],
  "How many district levels a world can hold, set by its size. When the land is full, grow elsewhere.": ["世界が持てる区画段階の数。大きさで決まる。土地がいっぱいなら他所で伸ばす。", "一個世界能容納多少區劃等級，由其大小決定。土地用盡時就到別處發展。", "一个世界能容纳多少区划等级，由其大小决定。土地用尽时就到别处发展。"],
  "How many people live in the nation (or on this world).": ["国(またはこの世界)に住む人の数。", "國家（或此世界）的居住人數。", "国家（或此世界）的居住人数。"],
  "How much debt (as a share of GDP) lenders will tolerate at your credit rating. Past it you are in fiscal crisis.": ["自国の格付で貸し手が許容する債務(GDP比)。超えると財政危機。", "在你的信用評級下，貸方能容忍的債務（佔GDP比例）。超過即陷入財政危機。", "在你的信用评级下，贷方能容忍的债务（占GDP比例）。超过即陷入财政危机。"],
  "How much each worker produces. Rising productivity — better technology, better tools — is where most growth in a developed economy comes from. In Simple mode it grows every month, faster the more research you do per person.": ["労働者一人の生産量。生産性の向上(より良い技術、より良い道具)が先進経済の成長の大半の源。簡易モードでは毎月伸び、一人あたりの研究が多いほど速い。", "每位勞工的產出量。生產力提升——更好的技術與工具——是已開發經濟大部分成長的來源。簡易模式中每月成長，人均研究越多成長越快。", "每位劳工的产出量。生产力提升——更好的技术与工具——是发达经济大部分增长的来源。简易模式中每月增长，人均研究越多增长越快。"],
  "How much of a good is on offer.": ["品がどれだけ出回っているか。", "某商品的供應量。", "某商品的供应量。"],
  "How much of a good people and businesses want to buy.": ["人々と企業が品をどれだけ買いたいか。", "人民與企業想購買某商品的數量。", "人民与企业想购买某商品的数量。"],
  "How much of what the world's sites make reaches a hub: roads and railways between the places people work and live.": ["世界の用地が作るもののうち拠点に届く割合。働く場所と住む場所を結ぶ道路と鉄道。", "世界各用地產出中能送達樞紐的比例：連接工作與居住地點的道路與鐵路。", "世界各用地产出中能送达枢纽的比例：连接工作与居住地点的道路与铁路。"],
  "How pleasant a place is to live, apart from what its people can buy: housing, infrastructure, safety, habitability and public services. Shown beside the standard of living; it is not part of it.": ["住民が買えるものとは別の、住みやすさ。住宅、社会基盤、治安、居住性、公共サービス。生活水準の横に示され、その一部ではない。", "一個地方有多宜居，與居民買得起什麼無關：住房、基礎設施、治安、宜居度與公共服務。顯示在生活水準旁，並不屬於它。", "一个地方有多宜居，与居民买得起什么无关：住房、基础设施、治安、宜居度与公共服务。显示在生活水平旁，并不属于它。"],
  "How safe lenders think your debt is, from AAA (very safe) down to CCC (near default). A worse rating means a lower debt ceiling and costlier borrowing.": ["貸し手が自国債務をどれほど安全と見るか。AAA(非常に安全)からCCC(債務不履行寸前)まで。格付が悪いほど債務上限は低く、借入は高くつく。", "貸方認為你的債務有多安全，從AAA（非常安全）到CCC（瀕臨違約）。評級越差，債務上限越低、借款越貴。", "贷方认为你的债务有多安全，从AAA（非常安全）到CCC（濒临违约）。评级越差，债务上限越低、借款越贵。"],
  "How tired of the war a nation is, from time and losses. Exhausted nations accept worse peace terms.": ["時間と損失から来る、国の戦争への疲れ。疲弊した国はより悪い講和条件を受け入れる。", "國家因時間與損失而對戰爭的厭倦程度。厭戰的國家會接受較差的和平條件。", "国家因时间与损失而对战争的厌倦程度。厌战的国家会接受较差的和平条件。"],
  "How well buildings' upkeep (their inputs) is supplied — the worst-supplied good. A building short of one of its own inputs slows down; the rest carry on.": ["建物の維持(投入)がどれだけ賄われているか。最も不足した品で決まる。投入の一つが不足した建物は遅くなり、他は続く。", "建築維護（投入）的供應程度——以供應最差的貨品為準。缺少自身某項投入的建築會減速；其餘照常。", "建筑维护（投入）的供应程度——以供应最差的货品为准。缺少自身某项投入的建筑会减速；其余照常。"],
  "How your nation is ruled: its branches, offices, laws and institutions.": ["国の統治の仕組み。部門、官職、法律、機関。", "你的國家如何被統治：其部門、官職、法律與機構。", "你的国家如何被统治：其部门、官职、法律与机构。"],
  "Indoor farming: twice a farm’s food from the same slot, but it runs on energy. For worlds short of room.": ["屋内農業。同じ枠で農場の二倍の食料を得るが、電力で動く。土地の乏しい世界向け。", "室內農業：同一格位可產出農場兩倍的糧食，但需耗電。適合空間不足的世界。", "室内农业：同一格位可产出农场两倍的粮食，但需耗电。适合空间不足的世界。"],
  "Interest paid on the national debt each year — money that buys nothing.": ["国債に毎年払う利息。何も買えないお金。", "每年支付的國債利息——買不到任何東西的錢。", "每年支付的国债利息——买不到任何东西的钱。"],
  "IOUs the state sells to borrow money: the buyer lends now and is repaid later with interest.": ["国が借金のために売る借用証書。買い手は今貸し、後に利息付きで返済を受ける。", "國家為借錢而出售的借據：買方現在出借，日後連本帶息獲償。", "国家为借钱而出售的借据：买方现在出借，日后连本带息获偿。"],
  "Keeps people alive. A shortage starves the population.": ["人々を生かす。不足すれば人口は飢える。", "維持人民生命。短缺會讓人口挨餓。", "维持人民生命。短缺会让人口挨饿。"],
  "Labor-intensive extraction. No power needed.": ["労働集約的な採掘。電力不要。", "勞力密集的開採。無需電力。", "劳力密集的开采。无需电力。"],
  "Landing fields and orbital lift — every one a key node on its world’s ground map, so an invader must take them all. Worlds have about two per billion people, mostly near the equator on a fast-spinning world, plus a few outliers; some are run by the state, some by private operators. In Simple mode each level adds trade capacity (a nation trades only as much as its spaceports can move) and burns rockets and spaceships; in Complex mode they make infrastructure and freight capacity.": ["着陸場と軌道揚力。どれも世界の地上図の要衝で、侵略者はすべてを取らねばならない。世界には10億人あたり約二つあり、高速自転の世界では主に赤道付近、加えて少数の外れ値。国営もあれば民間運営もある。簡易モードでは段階ごとに交易能力が増え(国は宇宙港が運べる分しか交易しない)、ロケットと宇宙船を消費する。複雑モードでは社会基盤と貨物容量を生む。", "起降場與軌道升力——每一座都是其世界地面圖上的要地，入侵者必須全數奪取。每十億人約有兩座，快速自轉的世界大多位於赤道附近，另有少數例外；部分國營、部分由民間經營。簡易模式中每級增加貿易量（國家的貿易量受限於其太空港運量），並消耗火箭與太空船；複雜模式中則產生基礎設施與貨運量。", "起降场与轨道升力——每一座都是其世界地面图上的要地，入侵者必须全数夺取。每十亿人约有两座，快速自转的世界大多位于赤道附近，另有少数例外；部分国营、部分由民间经营。简易模式中每级增加贸易量（国家的贸易量受限于其太空港运量），并消耗火箭与太空船；复杂模式中则产生基础设施与货运量。"],
  "Landing fields and orbital lift: the gate for trade with other nations. Each level adds trade capacity and is a key node on the ground map (it takes no district slot); it burns rockets and wears out spaceships.": ["着陸場と軌道揚力。他国との交易の門。段階ごとに交易能力が増え、地上図の要衝となる(区画枠を使わない)。ロケットを燃やし、宇宙船を消耗する。", "起降場與軌道升力：與他國貿易的門戶。每級增加貿易量，並是地面圖上的要地（不佔區劃格位）；消耗火箭並耗損太空船。", "起降场与轨道升力：与他国贸易的门户。每级增加贸易量，并是地面图上的要地（不占区划格位）；消耗火箭并耗损太空船。"],
  "Large general-purpose line hulls carrying every direct-fire type. Unlocks building the Cruiser.": ["あらゆる直射兵器を搭載する大型汎用戦列船体。巡洋艦の建造を解禁する。", "搭載各類直射武器的大型通用戰列艦體。解鎖巡洋艦建造。", "搭载各类直射武器的大型通用战列舰体。解锁巡洋舰建造。"],
  "Launch vehicles and boosters that lift cargo from a spaceport to orbit, where the freighters take it on.": ["宇宙港から軌道まで貨物を打ち上げる発射機とブースター。そこで貨物船が引き継ぐ。", "將貨物從太空港送上軌道的運載火箭與助推器，由貨船在軌道接手。", "将货物从太空港送上轨道的运载火箭与助推器，由货船在轨道接手。"],
  "Launch vehicles that lift cargo from spaceports to orbit — used up as spaceports work.": ["宇宙港から軌道へ貨物を上げる打ち上げ機。宇宙港の稼働で使い尽くされる。", "將貨物從太空港送上軌道的運載工具——隨太空港運作而消耗。", "将货物从太空港送上轨道的运载工具——随太空港运作而消耗。"],
  "Lecture halls, graduate schools and research institutes together. The grandest seat of learning — above all it drives the sciences, the largest broad source of research a world can build, and publishes its work as online services.": ["講堂、大学院、研究所を一体に。最も壮大な学府。何よりも科学を推し進め、世界が建てられる最大の幅広い研究源であり、成果を通信網として公開する。", "講堂、研究所與研究院匯集一處。最宏偉的學府——首要推動科學，是一個世界能建造的最大綜合研究來源，並以網路服務發表成果。", "讲堂、研究生院与研究院汇集一处。最宏伟的学府——首要推动科学，是一个世界能建造的最大综合研究来源，并以网络服务发表成果。"],
  "Living quarters on the base: housing for the world below, and a steadier crew.": ["基地の居住区。下の世界の住居となり、乗員も安定する。", "基地上的居住艙：為下方世界提供住房，乘員也更穩定。", "基地上的居住舱：为下方世界提供住房，乘员也更稳定。"],
  "Locomotives and rail move people and freight across the planet — strong infrastructure and freight capacity.": ["機関車と鉄道が惑星中で人と貨物を運ぶ。強力な社会基盤と貨物容量。", "機車與鐵路在行星上運送人員與貨物——強大的基礎設施與貨運量。", "机车与铁路在行星上运送人员与货物——强大的基础设施与货运量。"],
  "Long-range electromagnetic detection, and the countermeasures built to blind it.": ["長距離電磁探知と、それを盲目にするための対抗手段。", "長程電磁偵測，以及為使其失明而研發的反制手段。", "远程电磁侦测，以及为使其失明而研发的反制手段。"],
  "Long-range missile batteries for orbital bases: unlocks the Missile Battery module.": ["軌道基地用の長距離誘導弾砲台。誘導弾陣地の区画を解禁する。", "供軌道基地使用的長程飛彈砲台：解鎖飛彈陣地模組。", "供轨道基地使用的远程导弹炮台：解锁导弹阵地模组。"],
  "Long-range missiles: heavier return fire on besiegers than a gun battery.": ["長距離誘導弾。砲台より重い反撃を包囲者に浴びせる。", "長程飛彈：比砲台更猛烈地還擊圍攻者。", "远程导弹：比炮台更猛烈地还击围攻者。"],
  "Longer, far safer jumps for every hyperdrive ship of the nation, no refit. Consumes hyperium.": ["国のすべての超空間艦に、改装なしでより長く、はるかに安全な跳躍を。超空間鉱を消費する。", "國家所有超空間艦皆獲得更長、更安全的躍遷，無需改裝。消耗超空間礦。", "国家所有超空间舰皆获得更长、更安全的跃迁，无需改装。消耗超空间矿。"],
  "Lumber and hardwood worked into household furniture.": ["製材と硬材を家庭用家具に加工する。", "將木材與硬木加工成家用家具。", "将木材与硬木加工成家用家具。"],
  "Management, administration and overhead. Grows as the company grows.": ["経営、管理、間接費。企業の成長とともに大きくなる。", "管理、行政與經常開支。隨公司成長而擴大。", "管理、行政与经常开支。随公司成长而扩大。"],
  "Manual phosphate rock extraction.": ["手作業による燐鉱石の採掘。", "手工開採磷礦石。", "手工开采磷矿石。"],
  "Manual sulfur extraction from surface deposits. No power needed.": ["地表鉱床からの手作業の硫黄採取。電力不要。", "從地表礦床手工採硫。無需電力。", "从地表矿床手工采硫。无需电力。"],
  "Manufactured products a population consumes to stay content — insufficient supply drags down happiness and stability.": ["人々が満足を保つために消費する工業製品。供給不足は幸福度と安定を下げる。", "人口為保持滿足而消費的工業製品——供應不足會拖累幸福度與穩定。", "人口为保持满足而消费的工业制品——供应不足会拖累幸福度与稳定。"],
  "Manufacturing hyperium from exotic matter, rather than relying on rare natural deposits: Hyperium Refineries burn exotic matter to make it. Needs a stock of hyperium to work from, which it does not use up.": ["希少な天然鉱床に頼らず、異種物質から超空間鉱を製造する。超空間鉱精製所が異種物質を燃やしてそれを作る。作業には超空間鉱の在庫が必要だが、それは消費されない。", "以奇異物質製造超空間礦，而非依賴稀少的天然礦藏：超空間礦精煉廠燃燒奇異物質來生產。需要一批超空間礦作為基礎，但不會消耗它。", "以奇异物质制造超空间矿，而非依赖稀少的天然矿藏：超空间矿精炼厂燃烧奇异物质来生产。需要一批超空间矿作为基础，但不会消耗它。"],
  "Medium hulls with the structure and power for long-range missile racks. Unlocks building the Frigate.": ["長距離誘導弾架を載せる構造と電力を備えた中型船体。フリゲートの建造を解禁する。", "具備長程飛彈架所需結構與電力的中型艦體。解鎖巡防艦建造。", "具备远程导弹架所需结构与电力的中型舰体。解锁护卫舰建造。"],
  "Melts phosphate-bearing mineral feedstock into glass.": ["燐を含む鉱物原料を溶かして硝子にする。", "熔化含磷的礦物原料製成玻璃。", "熔化含磷的矿物原料制成玻璃。"],
  "Military industry: smelts the alloys ships and armies are built from. Its capacity is also what your military budget pays upkeep on.": ["軍需工業。艦と陸軍の材料となる合金を精錬する。その能力が軍事予算の維持費の基準にもなる。", "軍事工業：冶煉建造艦艇與陸軍所需的合金。其產能也是軍事預算維護費的計算基準。", "军事工业：冶炼建造舰艇与陆军所需的合金。其产能也是军事预算维护费的计算基准。"],
  "Mills grains into packaged groceries — a simple, robust processed-food supply.": ["穀物を挽いて包装食品にする。単純で頑健な加工食品の供給。", "將穀物碾製為包裝食品——簡單穩健的加工食品供應。", "将谷物碾制为包装食品——简单稳健的加工食品供应。"],
  "Mines far below the crust: twice the minerals from the same slot, for energy.": ["地殻のはるか下で採掘する。同じ枠で二倍の鉱物を、電力と引き換えに。", "深入地殼之下開採：同一格位兩倍礦物，以能源換取。", "深入地壳之下开采：同一格位两倍矿物，以能源换取。"],
  "Mines frozen volatiles — surface and subsurface water ice — and melts them into supply. The way an airless, frozen world or an outer moon waters itself; energy-hungry, but it needs neither rivers nor a sea.": ["凍った揮発性物質(地表と地下の水氷)を採掘し、溶かして供給する。大気のない凍った世界や外側の衛星が水を得る方法。電力を食うが、川も海もいらない。", "開採凍結的揮發物——地表與地下的水冰——融化後供應。無大氣的冰凍世界或外側衛星取水之道；耗電，但不需河流也不需海洋。", "开采冻结的挥发物——地表与地下的水冰——融化后供应。无大气的冰冻世界或外侧卫星取水之道；耗电，但不需河流也不需海洋。"],
  "Mining rigs and refineries for the rare hyperium deposits some worlds near Sol hold: draws hyperium from the deposits on bodies the nation owns, until they run dry.": ["太陽近傍のいくつかの世界にある希少な超空間鉱床のための採掘装置と精製所。国が所有する天体の鉱床から、枯渇するまで超空間鉱を採る。", "為太陽附近部分星球上稀有超空間礦藏而設的採礦設備與精煉廠：從本國擁有之天體的礦藏開採超空間礦，直到枯竭。", "为太阳附近部分星球上稀有超空间矿藏而设的采矿设备与精炼厂：从本国拥有之天体的矿藏开采超空间矿，直到枯竭。"],
  "Money banks have lent out that has not been repaid yet.": ["銀行が貸し出し、まだ返済されていないお金。", "銀行已貸出但尚未償還的錢。", "银行已贷出但尚未偿还的钱。"],
  "Money people and businesses keep in banks.": ["人々と企業が銀行に預けるお金。", "人民與企業存放在銀行的錢。", "人民与企业存放在银行的钱。"],
  "Money the state spends: the military, civil services, welfare, and interest on its debt.": ["国が使うお金。軍、民生サービス、福祉、債務利息。", "國家支出的錢：軍隊、民政服務、福利與債務利息。", "国家支出的钱：军队、民政服务、福利与债务利息。"],
  "Money the state takes in — mostly taxes.": ["国に入るお金。大半は税。", "國家收入的錢——主要是稅收。", "国家收入的钱——主要是税收。"],
  "Motors, generators and drives from steel and electronics — the electrical machinery power plants and advanced factories need.": ["鋼と電子機器から電動機、発電機、駆動装置。発電所と先進工場に必要な電気機械。", "以鋼與電子產品製造馬達、發電機與驅動器——發電廠與先進工廠所需的電機。", "以钢与电子产品制造马达、发电机与驱动器——发电厂与先进工厂所需的电机。"],
  "National debt as a share of one year's GDP — the usual yardstick for how heavy a debt is. Under ~60% is comfortable; well over 100% is dangerous.": ["一年のGDPに対する国債の割合。債務の重さの普通の物差し。約60%未満なら楽、100%を大きく超えると危険。", "國債佔一年GDP的比例——衡量債務輕重的常用標準。約60%以下尚屬寬鬆；遠超100%則危險。", "国债占一年GDP的比例——衡量债务轻重的常用标准。约60%以下尚属宽松；远超100%则危险。"],
  "Newtonian trajectory prediction — the ability to accurately calculate stellar body motion, orbital mechanics, and the effect of reaction-drive thrust against them.": ["ニュートン力学による軌道予測。天体の運動、軌道力学、そして反動推進がそれらに及ぼす効果を正確に計算する能力。", "牛頓軌道預測——精確計算天體運動、軌道力學以及反作用推進對其影響的能力。", "牛顿轨道预测——精确计算天体运动、轨道力学以及反作用推进对其影响的能力。"],
  "Notable people in your nation.": ["国の著名人。", "你國家的知名人物。", "你国家的知名人物。"],
  "Ongoing events and crises affecting your nation.": ["自国に影響する進行中の出来事と危機。", "影響你國家的進行中事件與危機。", "影响你国家的进行中事件与危机。"],
  "Orbital collector arrays at a stellar scale — the electromagnetic and structural engineering behind a Dyson swarm.": ["恒星規模の軌道集光アレイ。ダイソン群の背後にある電磁・構造工学。", "恆星尺度的軌道收集陣列——戴森群背後的電磁與結構工程。", "恒星尺度的轨道收集阵列——戴森群背后的电磁与结构工程。"],
  "Order and calm. Above 50% it boosts output; below 50% it hurts output; below 25% there is unrest and taxes go uncollected.": ["秩序と平穏。50%超で産出を押し上げ、50%未満で下げ、25%未満では不穏が起き税が集まらない。", "秩序與安寧。高於50%提升產出；低於50%削減產出；低於25%會發生動亂且稅收無法徵得。", "秩序与安宁。高于50%提升产出；低于50%削减产出；低于25%会发生动乱且税收无法征得。"],
  "Painstaking manual extraction of scarce metals.": ["希少金属の骨の折れる手作業採取。", "以艱辛的手工開採稀缺金屬。", "以艰辛的手工开采稀缺金属。"],
  "Panels that power the base.": ["基地に電力を供給する太陽電池板。", "為基地供電的太陽能板。", "为基地供电的太阳能板。"],
  "Particle accelerators, cryostats and theory groups pushing the physical sciences — the strongest single source of Physics research.": ["粒子加速器、極低温槽、理論班が物理科学を推し進める。物理研究の最強の単一源。", "粒子加速器、低溫恆溫器與理論團隊推進物理科學——最強的單一物理研究來源。", "粒子加速器、低温恒温器与理论团队推进物理科学——最强的单一物理研究来源。"],
  "Parts of a world developed for one purpose — industrial, academic, farming, mining, power, urban. Each district level houses a few buildings of its kind; develop more levels to build more.": ["一つの目的のために開発された世界の区域。工業、学術、農業、鉱業、発電、都市。各区画段階はその種類の建物をいくつか収める。もっと建てるには段階を開発する。", "為單一用途開發的世界區域——工業、學術、農業、礦業、發電、都市。每個區劃等級容納少數同類建築；開發更多等級才能建更多。", "为单一用途开发的世界区域——工业、学术、农业、矿业、发电、都市。每个区划等级容纳少数同类建筑；开发更多等级才能建更多。"],
  "Peace at home: unrest from people a demolition displaced, occupation, a war being fought, an enemy fleet in orbit.": ["国内の平穏。取り壊しで立ち退いた人々の不満、占領、戦争、軌道上の敵艦隊。", "國內的和平：拆遷造成的動盪、佔領、正在進行的戰爭、軌道上的敵艦隊。", "国内的和平：拆迁造成的动荡、占领、正在进行的战争、轨道上的敌舰队。"],
  "Pensions, healthcare, unemployment support and the like. It costs money but makes people happier (the poor and unemployed most).": ["年金、医療、失業手当など。費用はかかるが人々を幸せにする(特に貧困層と失業者)。", "退休金、醫療、失業救濟等。需要花錢，但能讓人民更快樂（尤其是貧困者與失業者）。", "退休金、医疗、失业救济等。需要花钱，但能让人民更快乐（尤其是贫困者与失业者）。"],
  "People a Colony Ship carries to a new world. They are taken out of the capital's population when the ship is built.": ["植民船が新世界へ運ぶ人々。船の建造時に首都の人口から差し引かれる。", "殖民船運往新世界的人。建造船隻時從首都人口中扣除。", "殖民船运往新世界的人。建造船只时从首都人口中扣除。"],
  "People of working age — about half the population. They fill the jobs buildings offer.": ["働く年齢の人々。人口のおよそ半分。建物が出す職を埋める。", "勞動年齡人口——約為人口的一半。他們填補建築提供的職位。", "劳动年龄人口——约为人口的一半。他们填补建筑提供的职位。"],
  "Physical cash in people's hands.": ["人々の手にある現物の現金。", "人民手中的實體現金。", "人民手中的实体现金。"],
  "Physical plating that absorbs damage after shields fail.": ["遮蔽が破れた後に損害を吸収する物理的な装甲板。", "護盾失效後吸收傷害的實體裝甲板。", "护盾失效后吸收伤害的实体装甲板。"],
  "Pick-and-cart coal digging. No power needed.": ["つるはしと台車の石炭採掘。電力不要。", "鎬與推車式的採煤。無需電力。", "镐与推车式的采煤。无需电力。"],
  "Placeholder: needs government systems, which the game does not have yet.": ["仮置き：まだゲームにない政治制度が必要。", "暫置：需要遊戲尚未具備的政府系統。", "暂置：需要游戏尚未具备的政府系统。"],
  "Points spent unlocking technologies. In Simple mode each lab researches its own tree (Physics, Society or Engineering Lab) — and all research also raises productivity.": ["技術の解禁に使う点。簡易モードでは研究所ごとに自分の系統(物理、社会、工学)を研究し、すべての研究は生産性も高める。", "用來解鎖科技的點數。簡易模式中，每座研究室研究自己的科技樹（物理、社會或工程實驗室）——所有研究也會提升生產力。", "用来解锁科技的点数。简易模式中，每座研究室研究自己的科技树（物理、社会或工程实验室）——所有研究也会提升生产力。"],
  "Political reach, spent to claim a system with a Starbase. Every nation earns a little each month (+2), up to 1,000. Founding a colony costs none. It cannot be traded or taken in a peace.": ["政治的影響力。宇宙基地で星系を主張するのに使う。どの国も毎月少し(+2)得て、上限は1,000。植民地の設立には要らない。取引も講和での奪取もできない。", "政治影響力，用於以星際基地主張星系。每個國家每月獲得少許（+2），上限1,000。建立殖民地不需花費。不可交易，也不能在和約中奪取。", "政治影响力，用于以星际基地主张星系。每个国家每月获得少许（+2），上限1,000。建立殖民地不需花费。不可交易，也不能在和约中夺取。"],
  "Political reach: spent to found colonies on new worlds. Every nation earns a little each month, up to a limit of 1,000. It cannot be traded or seized.": ["政治的影響力。新たな世界への植民に使う。どの国も毎月少しずつ得て、上限は1,000。取引も奪取もできない。", "政治影響力：用於在新世界建立殖民地。每個國家每月獲得少許，上限1,000。不可交易或奪取。", "政治影响力：用于在新世界建立殖民地。每个国家每月获得少许，上限1,000。不可交易或夺取。"],
  "Positions buildings offer. More jobs than workers leaves buildings understaffed; fewer leaves people unemployed.": ["建物が出す職。労働者より職が多ければ人手不足、少なければ失業が出る。", "建築提供的職位。職位多於勞工，建築就缺人；少於勞工，則有人失業。", "建筑提供的职位。职位多于劳工，建筑就缺人；少于劳工，则有人失业。"],
  "Power stations and grid. Plants here share transmission and maintenance.": ["発電所と送電網。ここの発電所は送電と保守を共有する。", "發電站與電網。此處電廠共享輸電與維護。", "发电站与电网。此处电厂共享输电与维护。"],
  "Powered crushing and flotation lift the yield of copper and nickel.": ["動力破砕と浮遊選鉱で銅とニッケルの収量が上がる。", "動力碎礦與浮選提高銅與鎳的產量。", "动力碎矿与浮选提高铜与镍的产量。"],
  "Powered harvesters and tools nearly double the cut.": ["動力伐採機と工具で伐採量がほぼ倍に。", "動力採伐機與工具讓伐木量近乎加倍。", "动力采伐机与工具让伐木量近乎加倍。"],
  "Powered harvesters lift the cut of high-grade hardwood.": ["動力伐採機が高級硬材の伐採量を引き上げる。", "動力採伐機提高高級硬木的伐取量。", "动力采伐机提高高级硬木的伐取量。"],
  "Powered refining more than doubles yield of rare metals.": ["動力精製で希少金属の収量が二倍以上に。", "動力精煉讓稀有金屬產量增加一倍以上。", "动力精炼让稀有金属产量增加一倍以上。"],
  "Powered rigs and heavy machinery reach far more crude.": ["動力掘削装置と重機で、はるかに多くの原油に届く。", "動力鑽井與重型機械能觸及遠更多的原油。", "动力钻井与重型机械能触及远更多的原油。"],
  "Powered strip mining doubles output, on excavating tools and grid power.": ["動力露天採掘で産出が倍に。掘削工具と電力で動く。", "動力露天開採讓產量加倍，需挖掘工具與電網電力。", "动力露天开采让产量加倍，需挖掘工具与电网电力。"],
  "Powered trawlers and processing raise the catch, on fuel and heavier gear.": ["動力トロール船と加工で漁獲が上がる。燃料と重い漁具を使う。", "動力拖網船與加工提高漁獲，需燃料與更重的漁具。", "动力拖网船与加工提高渔获，需燃料与更重的渔具。"],
  "Powers industry, labs, refineries and ships.": ["工業、研究所、精製所、艦を動かす。", "為工業、研究室、精煉廠與艦艇供電。", "为工业、研究室、精炼厂与舰艇供电。"],
  "Powers ship systems, orbital infrastructure, and most other production. The most universally consumed resource.": ["艦の機器、軌道インフラ、その他ほとんどの生産を動かす。最も広く消費される資源。", "驅動艦艇系統、軌道基礎設施及大部分生產。用途最廣的資源。", "驱动舰艇系统、轨道基础设施及大部分生产。用途最广的资源。"],
  "Precise modeling of a body's own gravity well, refined enough to plan a ship's trajectory around it rather than just predicting the body's motion.": ["天体自身の重力井戸を精密にモデル化し、天体の運動を予測するだけでなく、その周囲を回る艦の軌道まで計画できる。", "精密模擬天體自身的重力井，足以規劃艦艇繞行的軌跡，而不只是預測天體運動。", "精密模拟天体自身的重力井，足以规划舰艇绕行的轨迹，而不只是预测天体运动。"],
  "Processes livestock into meat for the food chain.": ["家畜を食肉に加工して食料連鎖へ送る。", "將牲畜加工成肉品送入食物鏈。", "将牲畜加工成肉品送入食物链。"],
  "Profits a company pays out to its shareholders.": ["企業が株主に払い出す利益。", "公司分配給股東的利潤。", "公司分配给股东的利润。"],
  "Pulps timber and hardwood with chemicals into paper.": ["原木と硬材を化学品でパルプにし、紙にする。", "以化學品將原木與硬木製漿造紙。", "以化学品将原木与硬木制浆造纸。"],
  "Pumps groundwater from aquifers — more power than surface treatment, but it works where there is no river to draw on.": ["帯水層から地下水を汲み上げる。地表水処理より電力を食うが、引く川がない所でも使える。", "從含水層抽取地下水——比地表水處理更耗電，但在沒有河流可取水之處也能運作。", "从含水层抽取地下水——比地表水处理更耗电，但在没有河流可取水之处也能运作。"],
  "Quarries and shafts. Mines here share rail, crushers and smelters.": ["採石場と坑道。ここの鉱山は鉄道、破砕機、製錬所を共有する。", "採石場與礦井。此處礦場共享鐵路、碎礦機與冶煉廠。", "采石场与矿井。此处矿场共享铁路、碎矿机与冶炼厂。"],
  "Rail and road across the planet: raises the world's infrastructure, and so its MARKET ACCESS — how much of its trade it can actually run.": ["惑星全体の鉄道と道路。世界の社会基盤、つまり市場への接続(実際に回せる交易量)を高める。", "遍布行星的鐵路與道路：提升世界的基礎設施，從而提升其市場通達度——實際能進行多少貿易。", "遍布行星的铁路与道路：提升世界的基础设施，从而提升其市场通达度——实际能进行多少贸易。"],
  "Rare matter that fuels warp drives. Found only in a few small natural deposits near Sol; nothing makes more.": ["歪曲航法の燃料となる希少物質。太陽近傍の少数の小さな天然鉱床にしかなく、増やす手段はない。", "作為曲速引擎燃料的稀有物質。僅見於太陽附近少數小型天然礦藏；無法製造更多。", "作为曲速引擎燃料的稀有物质。仅见于太阳附近少数小型天然矿藏；无法制造更多。"],
  "Rare, one-off materials that do not yet warrant their own dedicated category.": ["まだ独自の分類に値しない、希少で一点物の素材。", "尚不足以自成一類的稀有、單一材料。", "尚不足以自成一类的稀有、单一材料。"],
  "Raw material extracted from planets and asteroids — the basic input for construction, industry, and alloy production.": ["惑星や小惑星から採掘される原料。建設、工業、合金生産の基本的な投入物。", "從行星與小行星開採的原料——建設、工業與合金生產的基本投入。", "从行星与小行星开采的原料——建设、工业与合金生产的基本投入。"],
  "Raw material for industry and construction.": ["工業と建設の原料。", "工業與建設的原料。", "工业与建设的原料。"],
  "Redundant capacitor banks and finer-grained load balancing across the grid — real headroom for a heavier, more power-hungry loadout.": ["冗長化した蓄電器群と、網全体のより細かな負荷分散。より重く電力を食う装備への本物の余裕。", "冗餘電容組與更精細的全網負載平衡——為更重、更耗電的配置提供真正的餘裕。", "冗余电容组与更精细的全网负载平衡——为更重、更耗电的配置提供真正的余裕。"],
  "Refined from minerals — the structural material every ship hull and starbase is actually built from.": ["鉱物から精錬される。あらゆる艦の船体と宇宙基地の実際の構造材。", "由礦物精煉而成——所有艦體與星際基地實際使用的結構材料。", "由矿物精炼而成——所有舰体与星际基地实际使用的结构材料。"],
  "Refined structural metal — what ship hulls and military equipment are built from.": ["精錬された構造金属。艦の船体と軍事装備の素材。", "精煉的結構金屬——艦體與軍事裝備的材料。", "精炼的结构金属——舰体与军事装备的材料。"],
  "Refines crude oil and chemicals into cryogenic rocket propellant — the fuel that spaceport launches and rockets burn. Drawn from oil directly, so it does not compete with the fuel market.": ["原油と化学品を極低温ロケット推進剤に精製する。宇宙港の打ち上げとロケットが燃やす燃料。原油から直接引くので燃料市場と競合しない。", "將原油與化學品精煉成低溫火箭推進劑——太空港發射與火箭所燃燒的燃料。直接取自原油，因此不與燃料市場競爭。", "将原油与化学品精炼成低温火箭推进剂——太空港发射与火箭所燃烧的燃料。直接取自原油，因此不与燃料市场竞争。"],
  "Refines crude oil into fuel.": ["原油を燃料に精製する。", "將原油精煉成燃料。", "将原油精炼成燃料。"],
  "Refines hyperium (hyperdrive fuel) from exotic matter (warp fuel), at the one conversion rate. Needs Hyperium Synthesis. Energy hungry; it stops when the exotic matter runs out.": ["異種物質(歪曲燃料)から超空間鉱(超空間燃料)を一定の変換率で精製する。超空間鉱合成が必要。電力を多く食い、異種物質が尽きれば止まる。", "以固定轉換率從奇異物質（曲速燃料）精煉超空間礦（超空間引擎燃料）。需要超空間礦合成。耗電量大；奇異物質耗盡即停止。", "以固定转换率从奇异物质（曲速燃料）精炼超空间矿（超空间引擎燃料）。需要超空间矿合成。耗电量大；奇异物质耗尽即停止。"],
  "Relations with other nations: war, peace and events.": ["他国との関係。戦争、平和、出来事。", "與其他國家的關係：戰爭、和平與事件。", "与其他国家的关系：战争、和平与事件。"],
  "Research into the Engineering tree. All research also raises productivity.": ["工学系統の研究。すべての研究は生産性も高める。", "工程樹的研究。所有研究也會提升生產力。", "工程树的研究。所有研究也会提升生产力。"],
  "Research into the Physics tree. All research also raises productivity.": ["物理系統の研究。すべての研究は生産性も高める。", "物理樹的研究。所有研究也會提升生產力。", "物理树的研究。所有研究也会提升生产力。"],
  "Research into the Society tree. All research also raises productivity.": ["社会系統の研究。すべての研究は生産性も高める。", "社會樹的研究。所有研究也會提升生產力。", "社会树的研究。所有研究也会提升生产力。"],
  "Research trees. Spend research points to unlock new capabilities.": ["研究系統。研究点を使って新たな能力を解禁する。", "科技樹。花費研究點數解鎖新能力。", "科技树。花费研究点数解锁新能力。"],
  "Revenue minus spending. Positive is a surplus (money left over); negative is a deficit that has to be borrowed or printed.": ["歳入から歳出を引いたもの。正は黒字(余剰)、負は借入か紙幣発行で埋めるべき赤字。", "收入減去支出。為正是盈餘；為負則是必須借款或印鈔填補的赤字。", "收入减去支出。为正是盈余；为负则是必须借款或印钞填补的赤字。"],
  "Ring-scale orbital structures: unlocks the Orbital Ring tier (twelve module slots) and the Habitat Ring module. A ring circles a world over its equator.": ["環規模の軌道構造物。軌道環段階(区画枠12)と居住環区画を解禁する。環は赤道上空で世界を一周する。", "環形規模的軌道結構：解鎖軌道環等級（十二個模組槽）與居住環模組。環在赤道上空環繞一個世界。", "环形规模的轨道结构：解锁轨道环等级（十二个模组槽）与居住环模组。环在赤道上空环绕一个世界。"],
  "Robotic assembly lines raise throughput and skill demand, on heavy machinery and much more power.": ["自動組立ラインが処理量と技能需要を引き上げる。重機械とはるかに多くの電力で動く。", "機器人組裝線提高產能與技能需求，需重型機械與遠更多的電力。", "机器人组装线提高产能与技能需求，需重型机械与远更多的电力。"],
  "Room for the people against how many there are: the capacity of the world's settlements compared with its population. Below 100% the cities are crowded.": ["人数に対する住む余地。世界の集落の容量と人口の比。100%未満なら都市は過密。", "相對人口的居住空間：世界聚落容量與人口之比。低於100%表示城市擁擠。", "相对人口的居住空间：世界聚落容量与人口之比。低于100%表示城市拥挤。"],
  "Running the state: administration, police, courts, infrastructure upkeep.": ["国の運営。行政、警察、裁判所、インフラ維持。", "國家運作：行政、警察、法院、基礎設施維護。", "国家运作：行政、警察、法院、基础设施维护。"],
  "Shops, offices and markets: some amenities and a stream of taxable services output.": ["商店、事務所、市場。いくらかの生活施設と、課税できるサービス産出。", "商店、辦公室與市場：部分生活設施，以及可課稅的服務產出。", "商店、办公室与市场：部分生活设施，以及可课税的服务产出。"],
  "Shops, repairs and everyday services staffed by the working class.": ["労働者階級が働く商店、修理、日常サービス。", "由勞工階級經營的商店、維修與日常服務。", "由劳工阶级经营的商店、维修与日常服务。"],
  "Simple mode (Stellaris-style): a world's comfort, services and leisure. Every million people need a little; the city itself provides some, and Entertainment Centers, Commercial Zones and Clinics add more. A shortfall makes that world's people unhappy; a surplus makes them a little happier.": ["簡易モード(Stellaris風)：世界の快適さ、サービス、余暇。百万人ごとに少し必要。都市自体がいくらか供給し、娯楽施設、商業区、診療所がさらに加える。不足すればその世界の人々は不満、余れば少し満足する。", "簡易模式（Stellaris式）：一個世界的舒適、服務與休閒。每百萬人需要少許；城市本身提供部分，娛樂中心、商業區與診所再增加。短缺會讓該世界的人不快樂；有餘則稍感快樂。", "简易模式（Stellaris式）：一个世界的舒适、服务与休闲。每百万人需要少许；城市本身提供部分，娱乐中心、商业区与诊所再增加。短缺会让该世界的人不快乐；有余则稍感快乐。"],
  "Simple mode stratum: people working farms, mines, power plants and factories.": ["簡易モードの階層：農場、鉱山、発電所、工場で働く人々。", "簡易模式階層：在農場、礦場、發電廠與工廠工作的人。", "简易模式阶层：在农场、矿场、发电厂与工厂工作的人。"],
  "Simple mode stratum: skilled people working research labs and refineries. They want more consumer goods and electronics.": ["簡易モードの階層：研究所と精製所で働く熟練者。より多くの消費財と電子機器を求める。", "簡易模式階層：在研究室與精煉廠工作的專業人員。他們需要更多消費品與電子產品。", "简易模式阶层：在研究室与精炼厂工作的专业人员。他们需要更多消费品与电子产品。"],
  "Simple mode: amenities, and faster population growth on its world. Uses consumer goods.": ["簡易モード：生活施設と、その世界の人口増加の加速。消費財を使う。", "簡易模式：生活設施，並加快該世界的人口成長。使用消費品。", "简易模式：生活设施，并加快该世界的人口增长。使用消费品。"],
  "Simple mode: builds civilian spaceships from alloys and electronics.": ["簡易モード：合金と電子機器から民間宇宙船を建造する。", "簡易模式：以合金與電子產品建造民用太空船。", "简易模式：以合金与电子产品建造民用太空船。"],
  "Simple mode: builds launch rockets from alloys and energy.": ["簡易モード：合金と電力から打ち上げロケットを建造する。", "簡易模式：以合金與能源建造運載火箭。", "简易模式：以合金与能源建造运载火箭。"],
  "Simple mode: how much trade with other nations a nation’s spaceports can move each month, bought and sold together, valued at base prices. Short of rockets or spaceships, spaceports run slower and carry less. With no spaceport, a nation trades nothing.": ["簡易モード：国の宇宙港が毎月運べる他国との交易量(売買合計、基準価格で評価)。ロケットや宇宙船が不足すると宇宙港は遅くなり運ぶ量も減る。宇宙港がなければ交易はゼロ。", "簡易模式：國家太空港每月可運送的對外貿易量（買賣合計，以基準價計）。缺少火箭或太空船時，太空港運轉變慢、運量減少。沒有太空港就無法貿易。", "简易模式：国家太空港每月可运送的对外贸易量（买卖合计，以基准价计）。缺少火箭或太空船时，太空港运转变慢、运量减少。没有太空港就无法贸易。"],
  "Simple mode: how the central bank leans. Tight money raises the cost of credit — inflation falls, but construction slows. Loose money makes credit cheap — construction speeds up, but prices rise.": ["簡易モード：中央銀行の姿勢。引き締めは信用の費用を上げ、物価は下がるが建設は遅れる。緩和は信用を安くし、建設は速まるが物価は上がる。", "簡易模式：央行的取向。緊縮提高借貸成本——通膨下降，但建設放緩。寬鬆讓信貸便宜——建設加速，但物價上漲。", "简易模式：央行的取向。紧缩提高借贷成本——通胀下降，但建设放缓。宽松让信贷便宜——建设加速，但物价上涨。"],
  "Simple mode: industrial capacity — the total of your factories (civilian factories, alloy foundries, consumer goods factories, electronics plants). Each kind makes one product; build more of a kind to make more of it.": ["簡易モード：工業能力。工場(民生工場、合金鋳造所、消費財工場、電子機器工場)の合計。各種類は一つの製品を作る。増やすにはその種類を増設する。", "簡易模式：工業產能——你所有工廠（民用工廠、合金鑄造廠、消費品廠、電子廠）的總和。每種只生產一種產品；要多產某物就多建該種工廠。", "简易模式：工业产能——你所有工厂（民用工厂、合金铸造厂、消费品厂、电子厂）的总和。每种只生产一种产品；要多产某物就多建该种工厂。"],
  "Simple mode: makes construction points — what builds new buildings and district levels.": ["簡易モード：建設点を作る。新しい建物と区画段階を建てるもの。", "簡易模式：產生建設點數——用於建造新建築與區劃等級。", "简易模式：产生建设点数——用于建造新建筑与区划等级。"],
  "Simple mode: makes electronics, for research labs, fusion reactors and your specialists. Staffed by specialists.": ["簡易モード：研究所、核融合炉、専門職のための電子機器を作る。専門職が働く。", "簡易模式：為研究室、核融合反應爐與專業人員生產電子產品。由專業人員運作。", "简易模式：为研究室、核聚变反应堆与专业人员生产电子产品。由专业人员运作。"],
  "Simple mode: makes the consumer goods your people want — short of them, they get unhappy.": ["簡易モード：人々が求める消費財を作る。不足すれば不満を抱く。", "簡易模式：生產人民想要的消費品——短缺時他們會不快樂。", "简易模式：生产人民想要的消费品——短缺时他们会不快乐。"],
  "Simple mode: Market (more production and faster construction, specialists happier, workers less), Corporatist (balanced), or Planned (steadier, workers happier, higher tax yield, less production).": ["簡易モード：市場型(生産と建設が増え、専門職は満足、労働者は不満)、協調型(均衡)、計画型(安定し、労働者が満足、税収が多いが生産は減る)。", "簡易模式：市場型（產量更多、建設更快，專業人員較快樂、勞工較不快樂）、統合型（平衡）或計畫型（更穩定、勞工較快樂、稅收較高，但產量較少）。", "简易模式：市场型（产量更多、建设更快，专业人员较快乐、劳工较不快乐）、统合型（平衡）或计划型（更稳定、劳工较快乐、税收较高，但产量较少）。"],
  "Simple mode: shops and offices — some amenities, plus services that add to GDP (and so to taxes). No upkeep.": ["簡易モード：商店と事務所。いくらかの生活施設と、GDP(ひいては税)に加わるサービス。維持費なし。", "簡易模式：商店與辦公室——部分生活設施，加上計入GDP（因而計入稅收）的服務。無維護費。", "简易模式：商店与办公室——部分生活设施，加上计入GDP（因而计入税收）的服务。无维护费。"],
  "Simple mode: the most amenities per slot. Uses consumer goods; staffed by specialists.": ["簡易モード：枠あたり最多の生活施設。消費財を使い、専門職が働く。", "簡易模式：每格提供最多生活設施。使用消費品；由專業人員運作。", "简易模式：每格提供最多生活设施。使用消费品；由专业人员运作。"],
  "Simple mode: turns minerals and energy into alloys for ships and armies. Military upkeep follows your foundries, and a war economy builds many more.": ["簡易モード：鉱物と電力を艦と軍用の合金に変える。軍事維持費は鋳造所に比例し、戦時経済ではずっと多く建てる。", "簡易模式：將礦物與能源轉為艦艇與軍隊所需的合金。軍事維護費隨鑄造廠數量而定，戰時經濟會建造更多。", "简易模式：将矿物与能源转为舰艇与军队所需的合金。军事维护费随铸造厂数量而定，战时经济会建造更多。"],
  "Simple mode: twice a farm’s food in the same slot, for an energy upkeep — for crowded worlds short of land.": ["簡易モード：同じ枠で農場の二倍の食料。電力の維持が要る。土地の乏しい過密な世界向け。", "簡易模式：同一格位兩倍農場糧食，需能源維護——適合土地不足的擁擠世界。", "简易模式：同一格位两倍农场粮食，需能源维护——适合土地不足的拥挤世界。"],
  "Simple mode: twice a mine’s minerals in the same slot, for an energy upkeep.": ["簡易モード：同じ枠で鉱山の二倍の鉱物。電力の維持が要る。", "簡易模式：同一格位兩倍礦場礦物，需能源維護。", "简易模式：同一格位两倍矿场矿物，需能源维护。"],
  "Simple mode: two and a half times a power plant’s energy, run by specialists and using a little electronics.": ["簡易モード：発電所の2.5倍の電力。専門職が運転し、電子機器を少し使う。", "簡易模式：發電廠2.5倍的能源，由專業人員運轉並使用少量電子產品。", "简易模式：发电厂2.5倍的能源，由专业人员运转并使用少量电子产品。"],
  "Simple pumping of accessible crude.": ["取り出しやすい原油を単純に汲み上げる。", "單純抽取容易取得的原油。", "单纯抽取容易取得的原油。"],
  "Skims and compresses gas-giant hydrogen into metastable metallic hydrogen — an enormous, clean source of rocket fuel. A late-game megastructure-tier work.": ["巨大ガス惑星の水素をすくい取って圧縮し、準安定な金属水素にする。莫大でクリーンなロケット燃料源。終盤の巨大構造物級の施設。", "汲取並壓縮氣態巨行星的氫，製成亞穩態金屬氫——龐大潔淨的火箭燃料來源。後期巨型結構等級的設施。", "汲取并压缩气态巨行星的氢，制成亚稳态金属氢——庞大洁净的火箭燃料来源。后期巨型结构等级的设施。"],
  "Small boats and nets. Employs many, needs no inputs.": ["小舟と網。多くを雇い、投入は不要。", "小船與漁網。僱用眾多人力，無需投入。", "小船与渔网。雇用众多人力，无需投入。"],
  "Smelts iron ore with coal into steel, driven by heavy plant machinery.": ["鉄鉱石を石炭で製錬して鋼にする。重い工場機械で動く。", "以煤冶煉鐵礦成鋼，由重型廠房機械驅動。", "以煤冶炼铁矿成钢，由重型厂房机械驱动。"],
  "Social classes, by the kind of job a household works. Each has its own needs and happiness.": ["世帯の仕事の種類による社会階級。それぞれ独自の需要と幸福度を持つ。", "依家戶從事工作種類劃分的社會階級。各有其需求與幸福度。", "依家户从事工作种类划分的社会阶级。各有其需求与幸福度。"],
  "Something beyond every known field above — not yet understood, and not yet reachable.": ["既知のあらゆる分野の彼方にある何か。まだ理解されておらず、まだ手が届かない。", "超越上述所有已知領域的某種事物——尚未被理解，也尚無法觸及。", "超越上述所有已知领域的某种事物——尚未被理解，也尚无法触及。"],
  "Special and general relativity — how mass, energy, and spacetime itself relate.": ["特殊・一般相対性理論。質量、エネルギー、そして時空そのものがどう関係するか。", "狹義與廣義相對論——質量、能量與時空本身如何相互關聯。", "狭义与广义相对论——质量、能量与时空本身如何相互关联。"],
  "Spending more than you take in. The gap is covered by borrowing (debt) or printing money (inflation).": ["入る以上に使うこと。差額は借入(債務)か紙幣発行(物価上昇)で埋める。", "支出超過收入。差額以借款（債務）或印鈔（通膨）填補。", "支出超过收入。差额以借款（债务）或印钞（通胀）填补。"],
  "Stacked, climate-controlled grain growing — high yield in little space, on power, water and fertilizer. The backbone of food security on marginal worlds.": ["積層型の空調制御された穀物栽培。狭い場所で高い収量を、電力、水、肥料で。辺境の世界の食料安全保障の柱。", "層疊式、氣候控制的穀物種植——以電力、水與肥料在小空間獲得高產量。貧瘠世界糧食安全的支柱。", "层叠式、气候控制的谷物种植——以电力、水与肥料在小空间获得高产量。贫瘠世界粮食安全的支柱。"],
  "Steady, low-maintenance power from radioactive decay — ideal for anything that has to run unattended for a long time.": ["放射性崩壊による安定した低整備の電力。長期間無人で動き続けるべきものに最適。", "來自放射性衰變的穩定、低維護電力——最適合必須長期無人運作的設備。", "来自放射性衰变的稳定、低维护电力——最适合必须长期无人运作的设备。"],
  "Steel and lumber for finer goods, on heavier tooling than the basic line.": ["基本ラインより重い工具で、鋼と製材から上質な品を。", "以鋼與木材製作更精緻的商品，使用比基本線更重的工具。", "以钢与木材制作更精致的商品，使用比基本线更重的工具。"],
  "Steel and tools into the general industrial machinery that runs mills, plants and factories.": ["鋼と工具から、製造所や工場を動かす一般産業機械を作る。", "以鋼與工具製造驅動工廠與廠房的通用工業機械。", "以钢与工具制造驱动工厂与厂房的通用工业机械。"],
  "Steel, alloys, engines and electronics into automobiles for the population.": ["鋼、合金、機関、電子機器から人々のための自動車を作る。", "以鋼、合金、引擎與電子產品為人民製造汽車。", "以钢、合金、引擎与电子产品为人民制造汽车。"],
  "Steel, alloys, engines and electronics into ocean-going ships for planetary logistics.": ["鋼、合金、機関、電子機器から惑星物流用の外航船を作る。", "以鋼、合金、引擎與電子產品製造行星物流用的遠洋船。", "以钢、合金、引擎与电子产品制造行星物流用的远洋船。"],
  "Steel, alloys, precision machinery, electronics, heavy machinery and engines into spaceships — expensive, low-throughput, late-game capital construction.": ["鋼、合金、精密機械、電子機器、重機械、機関から宇宙船を作る。高価で処理量が少ない、終盤の資本財建設。", "以鋼、合金、精密機械、電子產品、重型機械與引擎製造太空船——昂貴、產量低的後期資本建設。", "以钢、合金、精密机械、电子产品、重型机械与引擎制造太空船——昂贵、产量低的后期资本建设。"],
  "Steel, machinery and engines into the heavy machinery that drives deep extraction, the heaviest industry and major construction.": ["鋼、機械、機関から、深部採掘、最重工業、大規模建設を動かす重機械を作る。", "以鋼、機械與引擎製造驅動深層開採、最重工業與大型建設的重型機械。", "以钢、机械与引擎制造驱动深层开采、最重工业与大型建设的重型机械。"],
  "Superheated water and powered pumps double sulfur yield.": ["過熱水と動力ポンプで硫黄の収量が倍に。", "過熱水與動力泵讓硫磺產量加倍。", "过热水与动力泵让硫磺产量加倍。"],
  "Surface-to-orbit guns: while one stands, enemies can’t land, and it damages their warships in orbit every day.": ["地対軌道砲。立っている間は敵が上陸できず、軌道上の敵艦に毎日損害を与える。", "地對軌道火砲：存在期間敵人無法登陸，且每日傷害軌道上的敵艦。", "地对轨道火炮：存在期间敌人无法登陆，且每日伤害轨道上的敌舰。"],
  "Synthesizes chemicals into dyes for textiles and luxury goods.": ["化学品から繊維と奢侈品用の染料を合成する。", "以化學品合成紡織品與奢侈品用的染料。", "以化学品合成纺织品与奢侈品用的染料。"],
  "Taking in more than you spend. The extra can pay down debt or build up reserves.": ["使う以上に入ること。余りで債務を返すか準備金を積める。", "收入超過支出。多出的部分可償債或累積儲備。", "收入超过支出。多出的部分可偿债或累积储备。"],
  "Tax on companies' profits.": ["企業の利益にかかる税。", "對企業利潤課徵的稅。", "对企业利润征收的税。"],
  "Tax on people's wages and earnings — usually a state's biggest source of revenue.": ["人々の賃金と稼ぎにかかる税。たいてい国の最大の歳入源。", "對人民工資與收入課徵的稅——通常是國家最大的收入來源。", "对人民工资与收入征收的税——通常是国家最大的收入来源。"],
  "Taxes on specific goods (fuel, luxuries…) collected when they are sold.": ["特定の品(燃料、奢侈品…)の販売時に徴収される税。", "在特定商品（燃料、奢侈品…）售出時課徵的稅。", "在特定商品（燃料、奢侈品…）售出时征收的税。"],
  "Technicians and physicians providing basic healthcare from medical supplies.": ["医療用品で基礎的な医療を提供する技師と医師。", "以醫療用品提供基本醫療的技術人員與醫師。", "以医疗用品提供基本医疗的技术人员与医师。"],
  "Test rigs, prototyping shops and materials labs turning theory into hardware — the strongest single source of Engineering research.": ["試験装置、試作工房、材料研究所が理論を装置に変える。工学研究の最強の単一源。", "試驗台、原型工坊與材料實驗室將理論化為硬體——最強的單一工程研究來源。", "试验台、原型工坊与材料实验室将理论化为硬件——最强的单一工程研究来源。"],
  "The armed forces. In the budget: what it costs to maintain them. In production: the share of industry making war material (alloys).": ["軍隊。予算では維持費。生産では軍需品(合金)を作る産業の割合。", "武裝部隊。在預算中是其維持費；在生產中是製造軍用物資（合金）的工業比例。", "武装部队。在预算中是其维持费；在生产中是制造军用物资（合金）的工业比例。"],
  "The basic laws of heat and energy transfer.": ["熱とエネルギー移動の基本法則。", "熱與能量傳遞的基本定律。", "热与能量传递的基本定律。"],
  "The biology of non-terrestrial life — how organisms that evolved elsewhere differ from Earth's own, and what that means for habitability and first contact.": ["地球外生命の生物学。他所で進化した生物が地球の生物とどう違い、それが居住性と最初の接触に何を意味するか。", "非地球生命的生物學——在別處演化的生物與地球生物有何不同，以及這對宜居度與第一次接觸意味著什麼。", "非地球生命的生物学——在别处演化的生物与地球生物有何不同，以及这对宜居度与第一次接触意味着什么。"],
  "The chamber of the Kingdom’s estates.": ["王国諸身分の議場。", "王國各等級的議事廳。", "王国各等级的议事厅。"],
  "The Emperor’s residence and the seat of the Imperial government, above Akakyō in Xanthe Terra.": ["皇帝の居所にして帝国政府の座。クサンテ大陸の赤京を見下ろす。", "皇帝的居所與帝國政府所在，俯瞰克桑西大陸的赤京。", "皇帝的居所与帝国政府所在，俯瞰克桑西大陆的赤京。"],
  "The Empire’s great fortress, guarding the capital.": ["首都を守る帝国の大要塞。", "守護首都的帝國大要塞。", "守护首都的帝国大要塞。"],
  "The fortified seat of the military government that rules Earth, in Chicago — the nerve centre of a declining empire.": ["地球を支配する軍事政府の要塞化された本拠。シカゴにある、衰退する帝国の中枢。", "統治地球之軍政府的設防總部，位於芝加哥——一個衰落帝國的神經中樞。", "统治地球之军政府的设防总部，位于芝加哥——一个衰落帝国的神经中枢。"],
  "The hardened command bunker guarding the capital.": ["首都を守る堅固な指揮壕。", "守護首都的強化指揮掩體。", "守护首都的强化指挥掩体。"],
  "The hyperdrive every human hull is built around: short jumps through hyperspace, burning hyperium, with a real chance of being lost.": ["人類のあらゆる船体が前提とする超空間航法。超空間鉱を燃やして超空間を短く跳躍するが、失われる危険は現実にある。", "人類所有艦體賴以建造的超空間引擎：燃燒超空間礦、短距躍遷穿越超空間，確實有失蹤的風險。", "人类所有舰体赖以建造的超空间引擎：燃烧超空间矿、短距跃迁穿越超空间，确实有失踪的风险。"],
  "The institution that issues the currency, sets interest rates and supervises banks — it fights inflation and keeps the financial system stable.": ["通貨を発行し、金利を決め、銀行を監督する機関。物価上昇と戦い、金融制度を安定させる。", "發行貨幣、制定利率並監管銀行的機構——對抗通膨並維持金融體系穩定。", "发行货币、制定利率并监管银行的机构——对抗通胀并维持金融体系稳定。"],
  "The interest rate minus inflation — what borrowing really costs.": ["金利から物価上昇率を引いたもの。借入の実際の費用。", "利率減去通膨——借款的真實成本。", "利率减去通胀——借款的真实成本。"],
  "The interstellar reserve currency, issued and regulated by the Central Bank of Earth — the common yardstick every nation's currency and economic metrics are priced against.": ["地球中央銀行が発行・管理する恒星間準備通貨。各国の通貨と経済指標の値付けの共通の物差し。", "由地球中央銀行發行與管理的星際儲備貨幣——各國貨幣與經濟指標計價的共同標準。", "由地球中央银行发行与管理的星际储备货币——各国货币与经济指标计价的共同标准。"],
  "The Kingdom’s castle, guarding the capital.": ["首都を守る王国の城。", "守護首都的王國城堡。", "守护首都的王国城堡。"],
  "The old imperial assembly, now a rubber stamp for the Command.": ["かつての帝国議会。今は司令部の追認機関にすぎない。", "昔日的帝國議會，如今只是司令部的橡皮圖章。", "昔日的帝国议会，如今只是司令部的橡皮图章。"],
  "The open forum where citizens petition and debate — the heart of Orion’s democracy.": ["市民が請願し議論する開かれた広場。オリオンの民主政の中心。", "市民請願與辯論的開放廣場——獵戶民主的核心。", "市民请愿与辩论的开放广场——猎户民主的核心。"],
  "The orbital half of a space elevator — pairs with a ground anchor below for huge fuel-free launch.": ["軌道エレベーターの軌道側。地上の基部と組めば、燃料なしで莫大な打ち上げができる。", "太空電梯的軌道端——與下方地面錨座配對，可無燃料大量發射。", "太空电梯的轨道端——与下方地面锚座配对，可无燃料大量发射。"],
  "The physics of exotic matter itself — matter with a mass-energy conversion ratio far beyond anything normal matter can achieve.": ["異種物質そのものの物理学。通常物質では到底及ばない質量エネルギー変換比を持つ物質。", "奇異物質本身的物理學——其質能轉換比遠超任何普通物質。", "奇异物质本身的物理学——其质能转换比远超任何普通物质。"],
  "The physics of hyperspace — a dimension outside the normal universe where time passes faster, reachable only by burning hyperium. Derived from first principles it is the work of centuries; a nation holding hyperium can instead study the real thing and skip most of it.": ["超空間の物理学。時間がより速く流れる通常宇宙の外の次元で、超空間鉱を燃やしてのみ到達できる。第一原理から導けば数世紀の仕事だが、超空間鉱を持つ国は実物を研究して大半を省略できる。", "超空間的物理學——一個位於正常宇宙之外、時間流逝更快的維度，唯有燃燒超空間礦才能抵達。從第一原理推導需要數百年；持有超空間礦的國家則可研究實物，省去大半功夫。", "超空间的物理学——一个位于正常宇宙之外、时间流逝更快的维度，唯有燃烧超空间矿才能抵达。从第一原理推导需要数百年；持有超空间矿的国家则可研究实物，省去大半功夫。"],
  "The physics of the very small.": ["極微の世界の物理学。", "極微世界的物理學。", "极微世界的物理学。"],
  "The population's overall happiness (weighted by head count). Stability follows it.": ["人口全体の幸福度(人数で重み付け)。安定はこれに従う。", "人口的整體幸福度（按人數加權）。穩定隨之變動。", "人口的整体幸福度（按人数加权）。稳定随之变动。"],
  "The price of borrowing money. Raising it cools the economy and fights inflation; cutting it encourages borrowing and growth.": ["お金を借りる値段。上げれば経済は冷え物価上昇と戦い、下げれば借入と成長を促す。", "借錢的價格。調升可讓經濟降溫、對抗通膨；調降則鼓勵借貸與成長。", "借钱的价格。上调可让经济降温、对抗通胀；下调则鼓励借贷与增长。"],
  "The Republic’s bastion, guarding the capital.": ["首都を守る共和国の稜堡。", "守護首都的共和國堡壘。", "守护首都的共和国堡垒。"],
  "The Republic’s citadel, guarding the capital.": ["首都を守る共和国の城塞。", "守護首都的共和國城塞。", "守护首都的共和国城塞。"],
  "The royal palace and seat of the Kingdom’s government, in Bellerive.": ["ベルリーヴにある王宮にして王国政府の座。", "王宮與王國政府所在，位於貝勒里夫。", "王宫与王国政府所在，位于贝勒里夫。"],
  "The seat of the Orion Republic’s government: its vast elected assembly, in Elysion.": ["オリオン共和国政府の座。エリュシオンにある巨大な民選議会。", "獵戶共和國政府所在：位於埃律西昂的龐大民選議會。", "猎户共和国政府所在：位于埃律西昂的庞大民选议会。"],
  "The seat of the Republic’s government, in Paphos.": ["パフォスにある共和国政府の座。", "共和國政府所在地，位於帕福斯。", "共和国政府所在地，位于帕福斯。"],
  "The share of deposits banks must keep in reserve instead of lending out. Higher = safer banks but less lending.": ["銀行が貸さずに準備として保つべき預金の割合。高いほど銀行は安全だが貸出は減る。", "銀行必須保留而不得貸出的存款比例。越高銀行越安全，但放款越少。", "银行必须保留而不得贷出的存款比例。越高银行越安全，但放款越少。"],
  "The share of healthcare and education the state funds for its people (Complex mode).": ["国が人々に資金を出す医療と教育の割合(複雑モード)。", "國家為人民負擔的醫療與教育比例（複雜模式）。", "国家为人民负担的医疗与教育比例（复杂模式）。"],
  "The share of the economy's income the state collects. Taxes pay for everything the government does — the military, services, welfare, interest on debt. Higher taxes mean more revenue, but take money out of people's and businesses' pockets.": ["国が徴収する経済所得の割合。税は軍、サービス、福祉、債務利息など政府のすべてを賄う。税が高いほど歳入は増えるが、人々と企業の懐からお金を奪う。", "國家徵收的經濟收入比例。稅收支付政府的一切開支——軍隊、服務、福利、債務利息。稅越高收入越多，但會從人民與企業口袋中拿走錢。", "国家征收的经济收入比例。税收支付政府的一切开支——军队、服务、福利、债务利息。税越高收入越多，但会从人民与企业口袋中拿走钱。"],
  "The state's cash on hand. If it would go negative, the shortfall is borrowed or printed.": ["国の手元資金。マイナスになりそうなら、不足分は借入か紙幣発行で賄う。", "國家的手頭現金。若將轉為負數，不足部分以借款或印鈔補足。", "国家的手头现金。若将转为负数，不足部分以借款或印钞补足。"],
  "The structure of the atom and its nucleus.": ["原子とその原子核の構造。", "原子及其原子核的結構。", "原子及其原子核的结构。"],
  "The study of living systems — anatomy, genetics, and the chemistry that drives them.": ["生命系の研究。解剖学、遺伝学、そしてそれを動かす化学。", "生命系統的研究——解剖學、遺傳學，以及驅動它們的化學。", "生命系统的研究——解剖学、遗传学，以及驱动它们的化学。"],
  "The theoretical basis for a warp drive: using exotic matter to warp space itself rather than moving through it.": ["歪曲航法の理論的基礎。空間の中を移動するのではなく、異種物質で空間そのものを歪める。", "曲速引擎的理論基礎：利用奇異物質扭曲空間本身，而非在其中移動。", "曲速引擎的理论基础：利用奇异物质扭曲空间本身，而非在其中移动。"],
  "The theoretical existence of dimensions beyond the familiar four.": ["見慣れた四次元を超える次元の理論的存在。", "超越熟知四維之外的維度在理論上的存在。", "超越熟知四维之外的维度在理论上的存在。"],
  "The unified theory of electricity, magnetism, and light.": ["電気、磁気、光の統一理論。", "電、磁與光的統一理論。", "电、磁与光的统一理论。"],
  "The worlds you own.": ["所有する世界。", "你擁有的世界。", "你拥有的世界。"],
  "Theatres, arenas and holo-dramas: plenty of amenities to keep people content.": ["劇場、競技場、立体劇。人々を満足させる豊富な生活施設。", "劇院、競技場與全息劇：大量生活設施，讓人民保持滿足。", "剧院、竞技场与全息剧：大量生活设施，让人民保持满足。"],
  "Traditional flooded-paddy cultivation. Labor-heavy, no inputs.": ["伝統的な水田耕作。労働集約的で投入不要。", "傳統水田耕作。勞力密集，無需投入。", "传统水田耕作。劳力密集，无需投入。"],
  "Turns chemicals into industrial and military explosives.": ["化学品を工業用・軍用の爆薬にする。", "將化學品製成工業與軍用炸藥。", "将化学品制成工业与军用炸药。"],
  "Turns seawater into fresh water on heavy power. Expensive, but a world covered in sea can water itself without a drop of rain.": ["大電力で海水を真水に変える。高価だが、海に覆われた世界は雨一滴なしで水を賄える。", "以大量電力將海水轉為淡水。昂貴，但海洋覆蓋的世界不需一滴雨也能自給用水。", "以大量电力将海水转为淡水。昂贵，但海洋覆盖的世界不需一滴雨也能自给用水。"],
  "Turns steel and tools into everyday consumer goods — a simple, robust supply.": ["鋼と工具を日用の消費財にする。単純で頑健な供給。", "將鋼與工具製成日常消費品——簡單穩健的供應。", "将钢与工具制成日常消费品——简单稳健的供应。"],
  "Two and a half times a power plant’s energy from the same slot, run by specialists; needs electronics.": ["同じ枠で発電所の2.5倍の電力。専門職が運転し、電子機器が必要。", "同一格位可產出發電廠2.5倍的能源，由專業人員運轉；需要電子產品。", "同一格位可产出发电厂2.5倍的能源，由专业人员运转；需要电子产品。"],
  "Universities and research labs. Clustered labs work better together, and each level of research park lifts the industry on the same world.": ["大学と研究所。集まった研究所はよく協働し、研究団地の各段階が同じ世界の工業を押し上げる。", "大學與研究室。聚集的研究室合作更佳，每一級研究園區都會提升同一世界的工業。", "大学与研究室。聚集的研究室合作更佳，每一级研究园区都会提升同一世界的工业。"],
  "Warships orbiting an enemy world pound it from space — defenses, ground forces and the world itself (devastation). Needs war and no enemy warships in orbit. Full bombardment also kills civilians.": ["敵の世界を周回する軍艦が宇宙から叩く。防衛、地上部隊、そして世界そのもの(荒廃)。戦争状態で、軌道に敵艦がいないことが必要。全面爆撃は民間人も殺す。", "環繞敵方世界的戰艦從太空轟擊——防禦、地面部隊與世界本身（破壞）。需要處於戰爭且軌道上無敵艦。全面轟炸也會殺死平民。", "环绕敌方世界的战舰从太空轰击——防御、地面部队与世界本身（破坏）。需要处于战争且轨道上无敌舰。全面轰炸也会杀死平民。"],
  "What one unit of a good costs.": ["品一単位の値段。", "一單位商品的價格。", "一单位商品的价格。"],
  "What one unit of your currency is worth in International Earth Dollars (IED). A stronger currency makes imports cheaper and exports earn less.": ["自国通貨一単位が国際地球ドル(IED)でいくらか。通貨が強いほど輸入は安く、輸出の稼ぎは減る。", "一單位本國貨幣值多少國際地球元（IED）。貨幣越強，進口越便宜、出口收入越少。", "一单位本国货币值多少国际地球元（IED）。货币越强，进口越便宜、出口收入越少。"],
  "What people consume each month. Food keeps them alive — a food shortage starves them. Consumer goods and electronics keep them happy.": ["人々が毎月消費するもの。食料は命をつなぎ、不足すれば飢える。消費財と電子機器は人々を満足させる。", "人民每月消費的東西。糧食維持生命——短缺會造成飢荒。消費品與電子產品讓人民快樂。", "人民每月消费的东西。粮食维持生命——短缺会造成饥荒。消费品与电子产品让人民快乐。"],
  "What people must consume to live and be content.": ["人々が生きて満足するために消費しなければならないもの。", "人民為生存與滿足而必須消費的東西。", "人民为生存与满足而必须消费的东西。"],
  "Where goods are bought and sold; prices rise when demand outruns supply and fall when supply outruns demand.": ["品が売買される場所。需要が供給を上回れば価格は上がり、供給が需要を上回れば下がる。", "買賣商品之處；需求超過供給時價格上漲，供給超過需求時下跌。", "买卖商品之处；需求超过供给时价格上涨，供给超过需求时下跌。"],
  "Where shares of companies are bought and sold.": ["企業の株が売買される場所。", "買賣公司股份的地方。", "买卖公司股份的地方。"],
  "Where the economy is pulling your exchange rate: low inflation, stability, low debt and a trade surplus make a currency stronger.": ["経済が為替相場をどちらへ引っ張るか。低い物価上昇、安定、少ない債務、貿易黒字は通貨を強くする。", "經濟將匯率往哪個方向拉：低通膨、穩定、低債務與貿易順差會使貨幣更強。", "经济将汇率往哪个方向拉：低通胀、稳定、低债务与贸易顺差会使货币更强。"],
  "Where the Imperial Diet sits: the Empire’s legislature, advising the throne.": ["帝国議会の議場。玉座に助言する帝国の立法府。", "帝國議會所在：向皇座進言的帝國立法機關。", "帝国议会所在：向皇座进言的帝国立法机关。"],
  "Where the Republic’s elected assembly meets.": ["共和国の選挙で選ばれた議会が開かれる場所。", "共和國民選議會的開會之處。", "共和国民选议会的开会之处。"],
  "Who is winning a war: territory occupied plus battles won. It decides what peace terms the enemy will accept.": ["戦争でどちらが勝っているか。占領した領土と勝った戦闘。敵が受け入れる講和条件を決める。", "戰爭中誰佔上風：佔領的領土加上贏得的戰鬥。決定敵方會接受的和平條件。", "战争中谁占上风：占领的领土加上赢得的战斗。决定敌方会接受的和平条件。"],
  "Who your people are — how many, what they do, how happy they are.": ["国の人々は誰か。何人いて、何をし、どれほど幸せか。", "你的人民是誰——有多少人、做什麼、有多快樂。", "你的人民是谁——有多少人、做什么、有多快乐。"],
  "Wool and synthetic fibre spun, woven and dyed into cloth and clothing.": ["羊毛と合成繊維を紡ぎ、織り、染めて布と衣服にする。", "將羊毛與合成纖維紡、織、染成布料與衣物。", "将羊毛与合成纤维纺、织、染成布料与衣物。"],
  "Workers without a job. They still need food and goods, produce nothing, and are unhappy.": ["職のない労働者。食料と品は必要だが何も生産せず、不満を抱く。", "沒有工作的勞工。仍需食物與商品，卻毫無產出，且不快樂。", "没有工作的劳工。仍需食物与商品，却毫无产出，且不快乐。"],
  "Your debt owned by foreigners — money that flows abroad as interest.": ["外国人が保有する自国の債務。利息として国外へ流れるお金。", "外國人持有的本國債務——以利息形式流向國外的錢。", "外国人持有的本国债务——以利息形式流向国外的钱。"],
  "Your fleets and armies: the navy, its shipyard, and the army.": ["艦隊と陸軍。海軍、その造船所、そして陸軍。", "你的艦隊與陸軍：海軍、其造船廠與陸軍。", "你的舰队与陆军：海军、其造船厂与陆军。"],
  "Your groups of ships.": ["艦の集団。", "你的艦艇編隊。", "你的舰艇编队。"],
  "Your nation's economy: budget, production, construction, trade.": ["国の経済。予算、生産、建設、交易。", "你國家的經濟：預算、生產、建設、貿易。", "你国家的经济：预算、生产、建设、贸易。"],
  "Your people: demographics, culture, religion, species.": ["国の人々。人口統計、文化、宗教、種族。", "你的人民：人口統計、文化、宗教、物種。", "你的人民：人口统计、文化、宗教、物种。"],
}
